INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nDi9l1ADQlS', 4, '{"title":"30","description":"<p>30、夫平人食少饮多，水停心下，久久成病，甚者则悸，微者短气，脉双弦者寒也，脉偏弦者饮也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002830,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '30、夫平人食少饮多，水停心下，久久成病，甚者则悸，微者短气，脉双弦者寒也，脉偏弦者饮也。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JVspOVQGbtQ', 4, '{"title":"31、夫短气有微饮者，当从小便去之","description":"<p>31、夫短气有微饮者，当从小便去之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002831,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '31、夫短气有微饮者，当从小便去之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xGyMoNO56oI', 4, '{"title":"32","description":"<p>32、病者脉伏，其人欲自利，利反快，虽利，心下续坚满，此为留饮，$f{甘遂半夏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002832,"note":"","videoMemo":"","fangList":["甘遂半夏汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '32、病者脉伏，其人欲自利，利反快，虽利，心下续坚满，此为留饮，$f{甘遂半夏汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
