INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tquGUpZR5X1', 4, '{"title":"36","description":"<p>36、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈者，$f{木防已汤}主之；不差，$f{木防已去石膏加茯苓芒硝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002836,"note":"","videoMemo":"","fangList":["木防已汤，木防已去石膏加茯苓芒硝汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '36、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈者，$f{木防已汤}主之；不差，$f{木防已去石膏加茯苓芒硝汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
