INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G2bSIODqQ1p', 4, '{"title":"42","description":"<p>42、膈间有水气，呕、吐、眩、悸者，$f{小半夏加茯苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002842,"note":"","videoMemo":"","fangList":["小半夏加茯苓汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '42、膈间有水气，呕、吐、眩、悸者，$f{小半夏加茯苓汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eWqZ1yJfig5', 4, '{"title":"43","description":"<p>43、病人脐下悸，吐涎沫而头眩者，此有水也，$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002843,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '43、病人脐下悸，吐涎沫而头眩者，此有水也，$f{五苓散}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xl4rzLCwsO6', 4, '{"title":"44","description":"<p>44、师曰：病有风水，有皮水，有正水，有石水，有黄汗。</p>\n<p></p>\n<p>           风水其脉自浮，其证骨节疼痛，恶风。</p>\n<p>           皮水其脉亦浮，其证尉肿，按之没指，不恶风，腹如鼓，不渴，当发其汗。</p>\n<p>           正水其脉沉迟，其证为喘。</p>\n<p>           石水其脉自沉，其证腹满不喘，当利其小便。</p>\n<p>           黄汗其脉沉迟，其证发热，胸满，四肢头面肿，久不愈，必致痈脓。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002844,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '44、师曰：病有风水，有皮水，有正水，有石水，有黄汗。 风水其脉自浮，其证骨节疼痛，恶风。 皮水其脉亦浮，其证尉肿，按之没指，不恶风，腹如鼓，不渴，当发其汗。 正水其脉沉迟，其证为喘。 石水其脉自沉，其证腹满不喘，当利其小便。 黄汗其脉沉迟，其证发热，胸满，四肢头面肿，久不愈，必致痈脓。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Zc98AI59vPX', 4, '{"title":"45、脉浮而洪，浮则为风，洪则为气","description":"<p>45、脉浮而洪，浮则为风，洪则为气。风气相搏，风强则为瘾疹，身体为痒，痒者为泻风，久为痂癞。气强则为水，难以俯仰，身体洪肿，汗出乃愈。恶风则虚，此为风水，不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002845,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '45、脉浮而洪，浮则为风，洪则为气。风气相搏，风强则为瘾疹，身体为痒，痒者为泻风，久为痂癞。气强则为水，难以俯仰，身体洪肿，汗出乃愈。恶风则虚，此为风水，不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x7ehwhjF7IK', 4, '{"title":"46、寸口脉沉滑者，中有水气，面目肿大有热，名曰风水","description":"<p>46、寸口脉沉滑者，中有水气，面目肿大有热，名曰风水。其人之目窠上微肿，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，亦曰风水。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002846,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '46、寸口脉沉滑者，中有水气，面目肿大有热，名曰风水。其人之目窠上微肿，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，亦曰风水。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K4QfGbKRo8h', 4, '{"title":"47","description":"<p>47、太阳病，脉浮而紧，法当骨节疼痛，今反不痛，体重而酸，其人不渴，此为风水，</p>\n<p>       汗出即愈，恶寒者此为极虚，发汗得之。渴而不恶寒者，此为皮水。</p>\n<p>       身肿而冷，状如周痹，胸中窒，不能食，反聚痛，躁不得眠，此为黄汗。</p>\n<p>       痛在骨节，咳而喘不渴者，此为正水，其状如肿，发汗则愈。然诸病此者若渴而下利，小便数者，皆不可发汗，但当利其小便。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002847,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '47、太阳病，脉浮而紧，法当骨节疼痛，今反不痛，体重而酸，其人不渴，此为风水， 汗出即愈，恶寒者此为极虚，发汗得之。渴而不恶寒者，此为皮水。 身肿而冷，状如周痹，胸中窒，不能食，反聚痛，躁不得眠，此为黄汗。 痛在骨节，咳而喘不渴者，此为正水，其状如肿，发汗则愈。然诸病此者若渴而下利，小便数者，皆不可发汗，但当利其小便。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('97OyIiM12sg', 4, '{"title":"48、心水为病，其身重而少气，不得卧，烦躁，阴肿","description":"<p>48、心水为病，其身重而少气，不得卧，烦躁，阴肿。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002848,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '48、心水为病，其身重而少气，不得卧，烦躁，阴肿。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FiPhtnScx2D', 4, '{"title":"49","description":"<p>49、肝水为病，其腹大，不能自转侧，胁下痛，津液微生，小便续通。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002849,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '49、肝水为病，其腹大，不能自转侧，胁下痛，津液微生，小便续通。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rm9488yV7mU', 4, '{"title":"50、肺水为病，其身肿，小便难，时时鸭溏","description":"<p>50、肺水为病，其身肿，小便难，时时鸭溏。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002850,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '50、肺水为病，其身肿，小便难，时时鸭溏。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rYA41y2vnbi', 4, '{"title":"51","description":"<p>51、脾水为病，其腹大，四肢苦重，津液不生，但苦少气，小便难。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002851,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '51、脾水为病，其腹大，四肢苦重，津液不生，但苦少气，小便难。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Pcm3eETFriV', 4, '{"title":"52","description":"<p>52、肾水为病，其腹大，脐肿，腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002852,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '52、肾水为病，其腹大，脐肿，腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bid4sw1dVLm', 4, '{"title":"53、诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈","description":"<p>53、诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002853,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '53、诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cPw7BeDKumH', 4, '{"title":"54","description":"<p>54、寸口脉沉而迟，沉则为水，迟则为寒，寒水相搏，脾气衰则骛溏，胃气衰则身肿，名曰水分。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002854,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '54、寸口脉沉而迟，沉则为水，迟则为寒，寒水相搏，脾气衰则骛溏，胃气衰则身肿，名曰水分。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e30g5NBqvJK', 4, '{"title":"55","description":"<p>55、少阳脉卑，少阴脉细，男子则小便不利；妇人则经水不利；名曰血分。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002855,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '55、少阳脉卑，少阴脉细，男子则小便不利；妇人则经水不利；名曰血分。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5xmkBdte9aX', 4, '{"title":"56","description":"<p>56、妇人经水，前断后病水者，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治，水去则经自下也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002856,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '56、妇人经水，前断后病水者，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治，水去则经自下也。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bPX3XB6doDt', 4, '{"title":"57","description":"<p>57、寸口脉沉而数，数则为出，沉则为入，出为阳实，入为阴结，趺阳脉微而弦，微则无胃气，弦则不得息；少阴脉沉而滑，沉为在里，滑则为实，沉滑相搏，血结胞门，其瘕不泻，经络不通，名曰血分。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002857,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '57、寸口脉沉而数，数则为出，沉则为入，出为阳实，入为阴结，趺阳脉微而弦，微则无胃气，弦则不得息；少阴脉沉而滑，沉为在里，滑则为实，沉滑相搏，血结胞门，其瘕不泻，经络不通，名曰血分。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ebN7JvrSKEI', 4, '{"title":"58","description":"<p>58、问曰：病者苦水，面目身体皆肿，四肢亦肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽状如炙肉，当感咳喘，审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相搏，结在关元，始时尚微，年盛不觉，阳衰之后，荣卫相干，阳损阴盛，结寒微动，肾气上冲，咽喉塞噎，胁下急痛，医以为留饮而大下之，沉紧不去，其病不除，复重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿，又与葶苈下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则咳喘逆，当先攻其冲气令止，乃治其咳，咳止，喘自差，先治新病，水当在后。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002858,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '58、问曰：病者苦水，面目身体皆肿，四肢亦肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽状如炙肉，当感咳喘，审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相搏，结在关元，始时尚微，年盛不觉，阳衰之后，荣卫相干，阳损阴盛，结寒微动，肾气上冲，咽喉塞噎，胁下急痛，医以为留饮而大下之，沉紧不去，其病不除，复重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿，又与葶苈下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则咳喘逆，当先攻其冲气令止，乃治其咳，咳止，喘自差，先治新病，水当在后。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sW5XHa7bb1E', 4, '{"title":"59","description":"<p>59、水之为病，其脉沉小者，属少阴为石水；沉迟者，属少阴为正水；浮而恶风者，为风水，属太阳，浮而不恶风者，为皮水，属太阳；虚肿者，属气分，发其汗即已，脉沉者，$f{麻黄附子甘草汤}主之；脉浮者，$f{麻黄加术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002859,"note":"","videoMemo":"","fangList":["麻黄附子甘草汤","麻黄加术汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '59、水之为病，其脉沉小者，属少阴为石水；沉迟者，属少阴为正水；浮而恶风者，为风水，属太阳，浮而不恶风者，为皮水，属太阳；虚肿者，属气分，发其汗即已，脉沉者，$f{麻黄附子甘草汤}主之；脉浮者，$f{麻黄加术汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yeub3xbPq1C', 4, '{"title":"60","description":"<p>60、风水，脉浮，身重，汗出，恶风者，$f{防已黄芪汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002860,"note":"","videoMemo":"","fangList":["防已黄芪汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '60、风水，脉浮，身重，汗出，恶风者，$f{防已黄芪汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pjdByfGTPdX', 4, '{"title":"61","description":"<p>61、风水，恶风，一身悉肿，脉浮不渴，续自汗出，无大热者，$f{越婢汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002861,"note":"","videoMemo":"","fangList":["越婢汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '61、风水，恶风，一身悉肿，脉浮不渴，续自汗出，无大热者，$f{越婢汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lIk2mv6Iy7c', 4, '{"title":"62","description":"<p>62、皮水，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防已茯苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002862,"note":"","videoMemo":"","fangList":["防已茯苓汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '62、皮水，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防已茯苓汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f4nKEB1I5bj', 4, '{"title":"63","description":"<p>63、里水，一身面目黄肿，其脉沉，小便不利，$f{甘草麻黄汤}主之；$f{越婢加术汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002863,"note":"","videoMemo":"","fangList":["甘草麻黄汤","越婢加术汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '63、里水，一身面目黄肿，其脉沉，小便不利，$f{甘草麻黄汤}主之；$f{越婢加术汤}亦主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aOvg2SarbEh', 4, '{"title":"64","description":"<p>64、问曰：黄汗之为病，身体肿，若重汗出而发热口渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，从何得之？</p>\n<p></p>\n<p>       师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002864,"note":"","videoMemo":"","fangList":["黄芪芍药桂枝汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '64、问曰：黄汗之为病，身体肿，若重汗出而发热口渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，从何得之？ 师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝汤}。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pMUOx4Z1F4I', 4, '{"title":"65","description":"<p>65、黄汗之病，两胫自冷，假令发热，此属历节，食已汗出，暮常盗汗，此荣气热也；若汗出已，反发热者，久久身必甲错；若发热不止者，久久必生恶疮；若身重，汗出已辙，轻者，久久身必瞤，瞤即胸痛；又从腰以上汗出，以下无汗，腰臗弛痛，如有物在皮中状，剧则不能食，身疼重，烦躁，小便不利，此为黄汗，$f{桂枝加黄芪汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002865,"note":"","videoMemo":"","fangList":["桂枝加黄芪汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '65、黄汗之病，两胫自冷，假令发热，此属历节，食已汗出，暮常盗汗，此荣气热也；若汗出已，反发热者，久久身必甲错；若发热不止者，久久必生恶疮；若身重，汗出已辙，轻者，久久身必瞤，瞤即胸痛；又从腰以上汗出，以下无汗，腰臗弛痛，如有物在皮中状，剧则不能食，身疼重，烦躁，小便不利，此为黄汗，$f{桂枝加黄芪汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t3ewKDEclOE', 4, '{"title":"66","description":"<p>66、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节痛，黄汗出，故曰历节。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002866,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '66、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节痛，黄汗出，故曰历节。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('exlNqwUD2In', 4, '{"title":"67","description":"<p>67、味酸则伤筋，筋伤则缓，名曰泄，咸则伤骨，骨伤则痿，名曰枯，枯泄相搏，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无御，四属断绝，身体赢瘦，独足肿大，黄汗出，两胫热，便为历节。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002867,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '67、味酸则伤筋，筋伤则缓，名曰泄，咸则伤骨，骨伤则痿，名曰枯，枯泄相搏，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无御，四属断绝，身体赢瘦，独足肿大，黄汗出，两胫热，便为历节。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MgVxuxxfs3k', 4, '{"title":"68","description":"<p>68、少阴，脉浮而弱，弱则血不足，浮则为风，风血相搏，即疼痛如掣。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002868,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '68、少阴，脉浮而弱，弱则血不足，浮则为风，风血相搏，即疼痛如掣。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RKJw6dLgaad', 4, '{"title":"69","description":"<p>69、肥盛之人，脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002869,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '69、肥盛之人，脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致也。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GzYoKF57Ug5', 4, '{"title":"70","description":"<p>70、诸肢节疼痛，身体赢瘦，脚肿如脱，头眩短气，温温欲吐者，$f{桂枝芍药知母甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002870,"note":"","videoMemo":"","fangList":["桂枝芍药知母甘草汤"],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '70、诸肢节疼痛，身体赢瘦，脚肿如脱，头眩短气，温温欲吐者，$f{桂枝芍药知母甘草汤}主之。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NAA5R7Lwl1k', 4, '{"title":"71","description":"<p>71、病历节，疼痛，不可屈伸，脉沉弱者，$f{乌头麻黄黄芪芍药甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002871,"note":"","videoMemo":"","fangList":["乌头麻黄黄芪芍药甘草汤"],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '71、病历节，疼痛，不可屈伸，脉沉弱者，$f{乌头麻黄黄芪芍药甘草汤}主之。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1J6CYImNzXQ', 4, '{"title":"72","description":"<p>72、病历节，疼痛，两足肿，大小便不利，脉沉紧者，$f{甘草麻黄汤}主之；脉沉而细数者，$f{越婢加术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002872,"note":"","videoMemo":"","fangList":["甘草麻黄汤","越婢加术汤"],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '72、病历节，疼痛，两足肿，大小便不利，脉沉紧者，$f{甘草麻黄汤}主之；脉沉而细数者，$f{越婢加术汤}主之。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yQN87q5TsaO', 4, '{"title":"73","description":"<p>73、师曰：寸口脉迟而涩，迟则为寒，涩为血不足，趺阳脉微而迟，微则为气，迟则为寒，胃气不足，则手足逆冷，荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼，阳前通则恶寒，阴前通则痹不仁，阴阳相得，其气乃行，大气一转，寒气乃散，实则失气，虚则遗溺，名曰气分。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002873,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '73、师曰：寸口脉迟而涩，迟则为寒，涩为血不足，趺阳脉微而迟，微则为气，迟则为寒，胃气不足，则手足逆冷，荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼，阳前通则恶寒，阴前通则痹不仁，阴阳相得，其气乃行，大气一转，寒气乃散，实则失气，虚则遗溺，名曰气分。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('huIvQHCwXx0', 4, '{"title":"74","description":"<p>74、气分，心下坚，大如盘，边如旋杯，$f{桂枝甘草麻黄生姜大枣细辛附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002874,"note":"","videoMemo":"","fangList":["桂枝甘草麻黄生姜大枣细辛附子汤"],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '74、气分，心下坚，大如盘，边如旋杯，$f{桂枝甘草麻黄生姜大枣细辛附子汤}主之。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k8gitNCNEWg', 4, '{"title":"75","description":"<p>75、水饮，心下坚，大如盘，边如旋杯，$f{枳实白术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002875,"note":"","videoMemo":"","fangList":["枳实白术汤"],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '75、水饮，心下坚，大如盘，边如旋杯，$f{枳实白术汤}主之。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('15Gaf3uUEAc', 4, '{"title":"76","description":"<p>76、小便不利，其人有水气，若渴者，$f{括蒌瞿麦薯蓣丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002876,"note":"","videoMemo":"","fangList":["括蒌瞿麦薯蓣丸"],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '76、小便不利，其人有水气，若渴者，$f{括蒌瞿麦薯蓣丸}主之。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9IFB4p2D1zO', 4, '{"title":"77","description":"<p>77、小便不利，其人有水气在血分者，$f{滑石乱发白鱼散}主之；$f{茯苓白术戎盐汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002877,"note":"","videoMemo":"","fangList":["滑石乱发白鱼散","茯苓白术戎盐汤"],"bieMing":""}}', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '2024-12-17T06:51:49.000Z', '77、小便不利，其人有水气在血分者，$f{滑石乱发白鱼散}主之；$f{茯苓白术戎盐汤}亦主之。', '2024-12-17T06:51:49.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Aeb40ueyOAl', 4, '{"title":"1","description":"<p>1、病人胸满、唇痿、舌青、口燥，但欲嗽水，不欲咽，无寒热，脉微大来迟，腹不满，其言我满，此为有瘀血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '1、病人胸满、唇痿、舌青、口燥，但欲嗽水，不欲咽，无寒热，脉微大来迟，腹不满，其言我满，此为有瘀血。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IYuLEmspi8j', 4, '{"title":"2","description":"<p>2、病人如有热状，烦满，口干燥而渴，其脉反无热，此为阴伏，是瘀血也，当下之，宜$f{下瘀血汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002902,"note":"","videoMemo":"","fangList":["下瘀血汤"],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2、病人如有热状，烦满，口干燥而渴，其脉反无热，此为阴伏，是瘀血也，当下之，宜$f{下瘀血汤}。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oNpbfGAeI5J', 4, '{"title":"3、膈间停留瘀血，若吐血色黑者，$f{桔梗汤}主之","description":"<p>3、膈间停留瘀血，若吐血色黑者，$f{桔梗汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002903,"note":"","videoMemo":"","fangList":["桔梗汤"],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '3、膈间停留瘀血，若吐血色黑者，$f{桔梗汤}主之。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
