INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vXIjgCCCpsV', 4, '{"title":"7、下血，先血而便者，此近血也，$f{赤豆当归散}主之","description":"<p>7、下血，先血而便者，此近血也，$f{赤豆当归散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002907,"note":"","videoMemo":"","fangList":["赤豆当归散"],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '7、下血，先血而便者，此近血也，$f{赤豆当归散}主之。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zbnyXh0SEeP', 4, '{"title":"8","description":"<p>8、师曰：病人面无色，无寒热，脉沉弦者，必衄血；脉浮而弱，按之则绝者，必下血，烦而咳者，必吐血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002908,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '8、师曰：病人面无色，无寒热，脉沉弦者，必衄血；脉浮而弱，按之则绝者，必下血，烦而咳者，必吐血。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kEjQHgqwh5O', 4, '{"title":"9、从春至夏衄血者，属太阳也；从秋至冬衄血者，属阳明也","description":"<p>9、从春至夏衄血者，属太阳也；从秋至冬衄血者，属阳明也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002909,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '9、从春至夏衄血者，属太阳也；从秋至冬衄血者，属阳明也。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rANdLQ9Ai3d', 4, '{"title":"10、尺脉浮，目睛晕黄者，衄未止也；黄去睛慧了者，知衄已止","description":"<p>10、尺脉浮，目睛晕黄者，衄未止也；黄去睛慧了者，知衄已止。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002910,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '10、尺脉浮，目睛晕黄者，衄未止也；黄去睛慧了者，知衄已止。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cCGXP31Df1K', 4, '{"title":"11","description":"<p>11、问曰：寸口脉微浮而涩，法当亡血，若汗出，设不汗出者云何？</p>\n<p></p>\n<p>           师曰：若身有疮，被刀斧所伤，亡血故也，此名金疮；无脓者，$f{王不留行散}主之；有脓者，$f{排脓散}主之，$f{排脓汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002911,"note":"","videoMemo":"","fangList":["王不留行散","排脓散","排脓汤"],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '11、问曰：寸口脉微浮而涩，法当亡血，若汗出，设不汗出者云何？ 师曰：若身有疮，被刀斧所伤，亡血故也，此名金疮；无脓者，$f{王不留行散}主之；有脓者，$f{排脓散}主之，$f{排脓汤}亦主之。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rhdb10fCCr3', 4, '{"title":"12","description":"<p>12、浸淫疮，从口流向四肢者，可治，从四肢流来入口者，不可治。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002912,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '12、浸淫疮，从口流向四肢者，可治，从四肢流来入口者，不可治。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('idCbg1Z6Ih9', 4, '{"title":"13、浸淫疮，$f{黄连粉}主之","description":"<p>13、浸淫疮，$f{黄连粉}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002913,"note":"","videoMemo":"","fangList":["黄连粉"],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '13、浸淫疮，$f{黄连粉}主之。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fhn9YARB2Mq', 4, '{"title":"14、诸脉浮数，法当发热，而反洒浙恶寒，若有痛处，当发其痈","description":"<p>14、诸脉浮数，法当发热，而反洒浙恶寒，若有痛处，当发其痈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002914,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '14、诸脉浮数，法当发热，而反洒浙恶寒，若有痛处，当发其痈。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CNhXc2F4PeB', 4, '{"title":"15","description":"<p>15、师曰：诸痈肿者，欲知有脓无脓？以手掩肿上，热者，为有脓；不热者，为无脓也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002915,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '15、师曰：诸痈肿者，欲知有脓无脓？以手掩肿上，热者，为有脓；不热者，为无脓也。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TNvq02vP9QF', 4, '{"title":"16","description":"<p>16、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为肠内有痈也，$f{薏苡附子败酱散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002916,"note":"","videoMemo":"","fangList":["薏苡附子败酱散"],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '16、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为肠内有痈也，$f{薏苡附子败酱散}主之。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('urF8JDNv007', 4, '{"title":"17","description":"<p>17、少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒，此为肠外有痈也；其脉沉紧者，脓未成也，下之当有血；脉洪数者，脓已成也，可下之，$f{大黄牡丹汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002917,"note":"","videoMemo":"","fangList":["大黄牡丹汤"],"bieMing":""}}', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '2024-12-17T07:15:59.000Z', '17、少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒，此为肠外有痈也；其脉沉紧者，脓未成也，下之当有血；脉洪数者，脓已成也，可下之，$f{大黄牡丹汤}主之。', '2024-12-17T07:15:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'q71IeKIPLgK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iydPFg9Jznc', 4, '{"title":"1","description":"<p>1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛；所以然者，责其极虚也，今阳虚，知在上焦，胸痹而痛者，以其脉弦故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002918,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛；所以然者，责其极虚也，今阳虚，知在上焦，胸痹而痛者，以其脉弦故也。', '2024-12-17T07:36:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'SKF0QSVG4Eo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Ahhali16CE', 4, '{"title":"2、平人无寒热，胸痹，短气不足以息者，实也","description":"<p>2、平人无寒热，胸痹，短气不足以息者，实也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002919,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '2、平人无寒热，胸痹，短气不足以息者，实也。', '2024-12-17T07:36:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'SKF0QSVG4Eo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0UBOtFv0oo5', 4, '{"title":"3","description":"<p>3、胸痹，喘、息、咳、唾，胸背痛，寸脉沉迟，关上小紧数者，$f{括蒌薤白白酒汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002920,"note":"","videoMemo":"","fangList":["括蒌薤白白酒汤"],"bieMing":""}}', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '3、胸痹，喘、息、咳、唾，胸背痛，寸脉沉迟，关上小紧数者，$f{括蒌薤白白酒汤}主之。', '2024-12-17T07:36:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'SKF0QSVG4Eo');
