INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DQsqFBdDMuj', 4, '{"title":"12、胸痹，心下痛，或有恶血积冷者，$f{九痛丸}主之","description":"<p>12、胸痹，心下痛，或有恶血积冷者，$f{九痛丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001029029,"note":"","videoMemo":"","fangList":["九痛丸"],"bieMing":""}}', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '2024-12-17T07:36:21.000Z', '12、胸痹，心下痛，或有恶血积冷者，$f{九痛丸}主之。', '2024-12-17T07:36:21.000Z', 1, NULL, '5IGM9t76quT', 'section', 'SKF0QSVG4Eo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Z8Cae17ILD', 4, '{"title":"1","description":"<p>1、师曰：妇人得平脉，阴脉小弱，其人呕，不能食，无寒热，此为妊娠，$f{桂枝汤}主之；于法六十日当有此证；设有医治逆者，却一月；加吐下者，则绝之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002929,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-17T09:15:26.000Z', '2024-12-17T09:15:26.000Z', '2024-12-17T09:15:26.000Z', '1、师曰：妇人得平脉，阴脉小弱，其人呕，不能食，无寒热，此为妊娠，$f{桂枝汤}主之；于法六十日当有此证；设有医治逆者，却一月；加吐下者，则绝之。', '2024-12-17T09:15:26.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T7yXxRT0Xsd', 4, '{"title":"2","description":"<p>2、妇人宿有症病，经断未及三月，而得漏下不止，胎动在脐上者，此为症痼害；妊娠六月动者，前三月经水利时胎也；下血者，断后三月衄也；所以血不止者，其症不去故也，当下其症，$f{桂枝茯苓丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002930,"note":"","videoMemo":"","fangList":["桂枝茯苓丸"],"bieMing":""}}', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '2、妇人宿有症病，经断未及三月，而得漏下不止，胎动在脐上者，此为症痼害；妊娠六月动者，前三月经水利时胎也；下血者，断后三月衄也；所以血不止者，其症不去故也，当下其症，$f{桂枝茯苓丸}主之。', '2024-12-17T09:05:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('95NTYOztt12', 4, '{"title":"3","description":"<p>3、妇人怀孕六七月，脉弦，发热，其胎愈胀，腹痛，恶寒，少腹如扇，所以然者，子藏开故也，当以$f{附子汤}温之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002931,"note":"","videoMemo":"","fangList":["附子汤"],"bieMing":""}}', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '3、妇人怀孕六七月，脉弦，发热，其胎愈胀，腹痛，恶寒，少腹如扇，所以然者，子藏开故也，当以$f{附子汤}温之。', '2024-12-17T09:05:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2qIoW3yX7jB', 4, '{"title":"4","description":"<p>4、师曰：妇人有漏下者；有半产后续下血都不绝者；假令妊娠腹中痛者，此为胞阻，$f{胶艾汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002932,"note":"","videoMemo":"","fangList":["胶艾汤"],"bieMing":""}}', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '4、师曰：妇人有漏下者；有半产后续下血都不绝者；假令妊娠腹中痛者，此为胞阻，$f{胶艾汤}主之。', '2024-12-17T09:05:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2HGS8nlrmZT', 4, '{"title":"5、妇人怀妊，腹中疞痛，$f{当归芍药散}主之","description":"<p>5、妇人怀妊，腹中疞痛，$f{当归芍药散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002933,"note":"","videoMemo":"","fangList":["当归芍药散"],"bieMing":""}}', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '2024-12-17T09:05:29.000Z', '5、妇人怀妊，腹中疞痛，$f{当归芍药散}主之。', '2024-12-17T09:05:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
