INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ckv6S78Qd7Y', 4, '{"title":"8","description":"<p>8、妊娠，有水气，小便不利，洒淅恶寒，起即头眩，$f{葵子茯苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002936,"note":"","videoMemo":"","fangList":["葵子茯苓散"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '8、妊娠，有水气，小便不利，洒淅恶寒，起即头眩，$f{葵子茯苓散}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mmgR9H3yw8F', 4, '{"title":"9","description":"<p>9、妇人妊娠，身无他病，宜常服$f{当归散}，则临产不难，产后亦免生他病。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002937,"note":"","videoMemo":"","fangList":["当归散"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '9、妇人妊娠，身无他病，宜常服$f{当归散}，则临产不难，产后亦免生他病。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jrdzLCDR31T', 4, '{"title":"10","description":"<p>10、妊娠，身有寒湿，或腹痛，或心烦，心痛，不能饮食，其胎跃跃动者，宜养之，$f{白术散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002938,"note":"","videoMemo":"","fangList":["白术散"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '10、妊娠，身有寒湿，或腹痛，或心烦，心痛，不能饮食，其胎跃跃动者，宜养之，$f{白术散}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('40xHsHBJoMb', 4, '{"title":"11","description":"<p>12、问曰：新产妇人有三病，一者病痉，二者郁冒，三者大便难，何谓也？</p>\n<p></p>\n<p>         师曰：新产血虚多汗出，喜中风，故令病痉；亡血，复汗，寒多，故令郁冒；亡津液胃燥，故大便难。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002939,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '12、问曰：新产妇人有三病，一者病痉，二者郁冒，三者大便难，何谓也？ 师曰：新产血虚多汗出，喜中风，故令病痉；亡血，复汗，寒多，故令郁冒；亡津液胃燥，故大便难。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iWn67KvVzav', 4, '{"title":"13、产妇郁冒，其脉微弱，呕不能食，大便反坚，但头汗出","description":"<p>13、产妇郁冒，其脉微弱，呕不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥则必冒，冒家欲解，必大汗出；以血虚下厥，孤阳上出，故头汗出也。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复；大便坚，呕不能食者，$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002940,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '13、产妇郁冒，其脉微弱，呕不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥则必冒，冒家欲解，必大汗出；以血虚下厥，孤阳上出，故头汗出也。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复；大便坚，呕不能食者，$f{小柴胡汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gDcWpVTKvWv', 4, '{"title":"13","description":"<p>14、郁冒病解，能食，七八日更发热者，此为胃实，$f{大承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002941,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '14、郁冒病解，能食，七八日更发热者，此为胃实，$f{大承气汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XVgWJbjBIMA', 4, '{"title":"14","description":"<p>15、产后腹中疞痛，若虚寒不足者，$f{当归生姜羊肉汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002942,"note":"","videoMemo":"","fangList":["当归生姜羊肉汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '15、产后腹中疞痛，若虚寒不足者，$f{当归生姜羊肉汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TV3Mo3xgLMs', 4, '{"title":"15","description":"<p>16、产后腹痛，烦满不得卧，不可下也，宜$f{枳实芍药散}和之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002943,"note":"","videoMemo":"","fangList":["枳实芍药散"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '16、产后腹痛，烦满不得卧，不可下也，宜$f{枳实芍药散}和之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2voAsaCV3oY', 4, '{"title":"16","description":"<p>17、师曰：产后腹痛，法当以$f{枳实芍药散}；假令不愈，必腹中有瘀血着脐下也，$f{下瘀血汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002944,"note":"","videoMemo":"","fangList":["枳实芍药散","下瘀血汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '17、师曰：产后腹痛，法当以$f{枳实芍药散}；假令不愈，必腹中有瘀血着脐下也，$f{下瘀血汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gxSAuJSE3FH', 4, '{"title":"17","description":"<p>18、产后七八日，无太阳证，少腹坚痛，此恶露不尽也；若不大便，烦躁，发热，脉微实者，宜和之；若日晡所烦躁，食则谵语，至夜即愈者，$f{大承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002945,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '18、产后七八日，无太阳证，少腹坚痛，此恶露不尽也；若不大便，烦躁，发热，脉微实者，宜和之；若日晡所烦躁，食则谵语，至夜即愈者，$f{大承气汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('56MuUlzwvfU', 4, '{"title":"18","description":"<p>19、产后中风，数十日不解，头痛，恶寒，发热，心下满，干呕，续自微汗出，$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002946,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '19、产后中风，数十日不解，头痛，恶寒，发热，心下满，干呕，续自微汗出，$f{小柴胡汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dCM1rBSynWm', 4, '{"title":"19","description":"<p>20、产后中风，发热，面赤，头痛，汗出而喘，脉弦数者，$f{竹叶汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002947,"note":"","videoMemo":"","fangList":["竹叶汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '20、产后中风，发热，面赤，头痛，汗出而喘，脉弦数者，$f{竹叶汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z3jVCsetwwz', 4, '{"title":"20","description":"<p>21、产后烦乱，呕逆，无外证者，此乳中虚也，$f{竹皮大丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002948,"note":"","videoMemo":"","fangList":["竹皮大丸"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '21、产后烦乱，呕逆，无外证者，此乳中虚也，$f{竹皮大丸}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8KvVT7VNTYc', 4, '{"title":"22、产后下利，脉虚极者，$f{白头翁加甘草阿胶汤}主之","description":"<p>22、产后下利，脉虚极者，$f{白头翁加甘草阿胶汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002949,"note":"","videoMemo":"","fangList":["白头翁加甘草阿胶汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '22、产后下利，脉虚极者，$f{白头翁加甘草阿胶汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u4r0EjWQrlh', 4, '{"title":"23、妇人咽中如有炙脔者，$f{半夏厚朴茯苓生姜汤}主之","description":"<p>23、妇人咽中如有炙脔者，$f{半夏厚朴茯苓生姜汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002950,"note":"","videoMemo":"","fangList":["半夏厚朴茯苓生姜汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '23、妇人咽中如有炙脔者，$f{半夏厚朴茯苓生姜汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sum80fc4JrD', 4, '{"title":"23","description":"<p>24、妇人脏燥，悲伤欲哭，数欠伸，象如神灵所作者，$f{甘草小麦大枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002951,"note":"","videoMemo":"","fangList":["甘草小麦大枣汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '24、妇人脏燥，悲伤欲哭，数欠伸，象如神灵所作者，$f{甘草小麦大枣汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YOXtrDEsSOL', 4, '{"title":"24","description":"<p>25、妇人吐涎沫，医反下之，心下即痞，当先治其吐涎沫，后治其痞，治吐宜$f{桔梗甘草茯苓泽泻汤}；治痞宜$f{泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002952,"note":"","videoMemo":"","fangList":["桔梗甘草茯苓泽泻汤","泻心汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '25、妇人吐涎沫，医反下之，心下即痞，当先治其吐涎沫，后治其痞，治吐宜$f{桔梗甘草茯苓泽泻汤}；治痞宜$f{泻心汤}。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V5V6sOAn2xg', 4, '{"title":"26、妇人之病，因虚积冷结，为诸经水断绝，血结胞门","description":"<p>26、妇人之病，因虚积冷结，为诸经水断绝，血结胞门。或绕脐疼痛，状如寒疝；或痛在关元，肌若鱼鳞；或阴中掣痛，少腹恶寒；或引腰脊，或下气街；此皆带下。万病一言，察其寒、热、虚、实、紧、弦、行其针药，各探其源，子当辨记，勿谓不然。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002953,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '26、妇人之病，因虚积冷结，为诸经水断绝，血结胞门。或绕脐疼痛，状如寒疝；或痛在关元，肌若鱼鳞；或阴中掣痛，少腹恶寒；或引腰脊，或下气街；此皆带下。万病一言，察其寒、热、虚、实、紧、弦、行其针药，各探其源，子当辨记，勿谓不然。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rEjqwgUS4wP', 4, '{"title":"26","description":"<p>27、问曰：妇人年五十所，病下血数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？</p>\n<p></p>\n<p>       师曰：此病属带下，何以知之？曾经半产，瘀血在少腹不去，故唇口干燥也，$f{温经汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002954,"note":"","videoMemo":"","fangList":["温经汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '27、问曰：妇人年五十所，病下血数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？ 师曰：此病属带下，何以知之？曾经半产，瘀血在少腹不去，故唇口干燥也，$f{温经汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wNFM2kUedqz', 4, '{"title":"27","description":"<p>28、经水不利，少腹满痛，或一月再经者，$f{王瓜根散}主之。阴肿者，亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002955,"note":"","videoMemo":"","fangList":["王瓜根散"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '28、经水不利，少腹满痛，或一月再经者，$f{王瓜根散}主之。阴肿者，亦主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZS0hSfRE4Mz', 4, '{"title":"28","description":"<p>29、妇人半产若漏下者，$f{旋覆花汤}主之；脉虚弱者，$f{黄芪当归汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002956,"note":"","videoMemo":"","fangList":["黄芪当归汤","旋覆花汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '29、妇人半产若漏下者，$f{旋覆花汤}主之；脉虚弱者，$f{黄芪当归汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
