INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FzgzI3v3kpO', 4, '{"title":"30","description":"<p>31、妇人少腹满，如敦状，小便微难而不渴，或经后产后者，此为水与血俱结在血室也，$f{大黄甘遂阿胶汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002958,"note":"","videoMemo":"","fangList":["大黄甘遂阿胶汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '31、妇人少腹满，如敦状，小便微难而不渴，或经后产后者，此为水与血俱结在血室也，$f{大黄甘遂阿胶汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('awEwWLvBEdu', 4, '{"title":"31","description":"<p>32、妇人时腹痛，经水时行时止，止而复行者，$f{抵当汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002959,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '32、妇人时腹痛，经水时行时止，止而复行者，$f{抵当汤}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6wOTbZyH0gM', 4, '{"title":"32","description":"<p>33、妇人经水闭，脏坚癖，下白物不止，此中有干血也，$f{矾石丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002960,"note":"","videoMemo":"","fangList":["矾石丸"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '33、妇人经水闭，脏坚癖，下白物不止，此中有干血也，$f{矾石丸}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ovM74w4I4jH', 4, '{"title":"33","description":"<p>34、妇人六十二种风证，腹中气血如刺痛者，$f{红蓝花酒}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002961,"note":"","videoMemo":"","fangList":["红蓝花酒"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '34、妇人六十二种风证，腹中气血如刺痛者，$f{红蓝花酒}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c53CwVephuL', 4, '{"title":"34","description":"<p>35、妇人腹中诸病痛者，$f{当归芍药散}主之；$f{小建中汤}亦主之；</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002962,"note":"","videoMemo":"","fangList":["当归芍药散","小建中汤"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '35、妇人腹中诸病痛者，$f{当归芍药散}主之；$f{小建中汤}亦主之；', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mGxNTmlORTj', 4, '{"title":"35","description":"<p>36、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？</p>\n<p></p>\n<p>          师曰：此名转胞，不得溺也，以胞系了戾，故致此病，但利小便则愈，$f{肾气丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002963,"note":"","videoMemo":"","fangList":["肾气丸"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '36、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？ 师曰：此名转胞，不得溺也，以胞系了戾，故致此病，但利小便则愈，$f{肾气丸}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n7K8c3gSFL5', 4, '{"title":"37、妇人阴寒，$f{蛇床子散}主之","description":"<p>37、妇人阴寒，$f{蛇床子散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002964,"note":"","videoMemo":"","fangList":["蛇床子散"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '37、妇人阴寒，$f{蛇床子散}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
