INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8vU083SjCgO', 4, '{"title":"38","description":"<p>39、胃气下泄，阴吹而喧，如失气者，此谷道实也，$f{猪膏发煎}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002966,"note":"","videoMemo":"","fangList":["猪膏发煎"],"bieMing":""}}', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '2024-12-17T09:05:28.000Z', '39、胃气下泄，阴吹而喧，如失气者，此谷道实也，$f{猪膏发煎}主之。', '2024-12-17T09:05:28.000Z', 1, NULL, '5IGM9t76quT', 'section', 'qQPCJTZga3G');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dR1IAFFs7UI', 1, '{"title":"麻黄汤","description":"<p>$u{麻黄}$w{三两、去节}    $u{桂枝}$w{二两、去皮}    $u{甘草}$w{一两、炙}    $u{杏仁}$w{七十个、去皮尖}</p>\n<p>\t右四味，以水九升，先煮麻黄减二升，去上沫，纳诸药，煮取二升半，去滓，温服八合，覆取微似汗，不须粥饮，余如桂枝法将息，桂枝汤见后卷。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":1,"yaoCount":4,"drinkNum":3,"yaoList":["杏仁","甘草","桂枝","麻黄"],"fangList":[],"fangYaoList":[{"yaoId":"Hs7PKqMqKRj","amount":"七十个","weight":null,"suffix":"","showName":"杏仁","extraProcess":"去皮尖"},{"yaoId":null,"amount":"一两","weight":null,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":null,"suffix":"","showName":"桂枝","extraProcess":"去皮"},{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":null,"suffix":"","showName":"麻黄","extraProcess":"去节"}]}}', '2024-12-07T03:58:32.000Z', '2024-12-07T03:58:32.000Z', '2024-12-07T03:58:32.000Z', '$u{麻黄}$w{三两、去节} $u{桂枝}$w{二两、去皮} $u{甘草}$w{一两、炙} $u{杏仁}$w{七十个、去皮尖} 右四味，以水九升，先煮麻黄减二升，去上沫，纳诸药，煮取二升半，去滓，温服八合，覆取微似汗，不须粥饮，余如桂枝法将息，桂枝汤见后卷。', '2024-12-07T03:58:32.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mV6GZ8chSDc', 1, '{"title":"白虎汤","description":"<p>$u{知母}$w{六两}    $u{石膏}$w{一斤、碎}    $u{甘草}$w{二两、炙}    $u{粳米}$w{六合}</p>\n<p></p>\n<p>     右四味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":2,"yaoCount":4,"drinkNum":3,"yaoList":["知母","石膏","甘草","粳米"],"fangList":[],"fangYaoList":[{"yaoId":"2gRWUBY7CiY","amount":"六合","weight":null,"suffix":"","showName":"粳米","extraProcess":""},{"yaoId":null,"amount":"二两","weight":null,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"S7mhkBtEhPL","amount":"一斤","weight":null,"suffix":"","showName":"石膏","extraProcess":"锤捣碎"},{"yaoId":"PeV28d5T6et","amount":"六两","weight":null,"suffix":"","showName":"知母","extraProcess":"切"}]}}', '2024-12-07T05:44:32.000Z', '2024-12-07T05:44:32.000Z', '2024-12-07T05:44:32.000Z', '$u{知母}$w{六两} $u{石膏}$w{一斤、碎} $u{甘草}$w{二两、炙} $u{粳米}$w{六合} 右四味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。', '2024-12-07T05:44:32.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aAGtOE4hG1O', 1, '{"title":"大承气汤","description":"<p>$u{大黄}$w{四两、 (酒洗)}    $u{厚朴}$w{半斤 (炙去皮)}    $u{枳实}$w{五枚、(炙)}    $u{芒硝}$w{三合}</p>\n<p></p>\n<p>\t右四味，以水一斗，先煮二物，取五升，去滓，纳大黄，更煮取二升，去滓，纳芒硝，更上微火一两沸，分温再服，得下余勿服。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":3,"yaoCount":4,"drinkNum":2,"yaoList":["大黄","厚朴","枳实","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"J7mL6gla0C0","amount":"三合","weight":null,"suffix":"","showName":"芒硝","extraProcess":""},{"yaoId":"FRaBwjHoVui","amount":"五枚","weight":null,"suffix":"","showName":"枳实","extraProcess":"炙"},{"yaoId":"8714SID7nWu","amount":"半斤","weight":null,"suffix":"","showName":"厚朴","extraProcess":"炙"},{"yaoId":"To31b37bc6Z","amount":"四两、酒","weight":null,"suffix":"","showName":"大黄","extraProcess":"洗"}]}}', '2024-12-07T05:56:47.000Z', '2024-12-07T05:56:47.000Z', '2024-12-07T05:56:47.000Z', '$u{大黄}$w{四两、 (酒洗)} $u{厚朴}$w{半斤 (炙去皮)} $u{枳实}$w{五枚、(炙)} $u{芒硝}$w{三合} 右四味，以水一斗，先煮二物，取五升，去滓，纳大黄，更煮取二升，去滓，纳芒硝，更上微火一两沸，分温再服，得下余勿服。', '2024-12-07T05:56:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ojkJ7F1qTsB', 1, '{"title":"小承气汤","description":"<p>$u{大黄}$w{四两、(酒洗)}    $u{厚朴}$w{二两、(炙去皮)}    $u{枳实}$w{三枚 (炙)}</p>\n<p></p>\n<p>         右三味，以水四升，煮取一升二合，去滓分温再服，$m{初服更衣者，停后服，不尔者，尽饮之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":4,"yaoCount":3,"drinkNum":2,"yaoList":["大黄","厚朴","枳实"],"fangList":[],"fangYaoList":[{"yaoId":"FRaBwjHoVui","amount":"三枚","weight":null,"suffix":"","showName":"枳实","extraProcess":"炙"},{"yaoId":"8714SID7nWu","amount":"二两、去皮","weight":null,"suffix":"","showName":"厚朴","extraProcess":"炙"},{"yaoId":"To31b37bc6Z","amount":"四两、酒","weight":null,"suffix":"","showName":"大黄","extraProcess":"洗"}]}}', '2024-12-07T06:14:39.000Z', '2024-12-07T06:14:39.000Z', '2024-12-07T06:14:39.000Z', '$u{大黄}$w{四两、(酒洗)} $u{厚朴}$w{二两、(炙去皮)} $u{枳实}$w{三枚 (炙)} 右三味，以水四升，煮取一升二合，去滓分温再服，$m{初服更衣者，停后服，不尔者，尽饮之。}', '2024-12-07T06:14:39.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ojf5x51repw', 1, '{"title":"调胃承气汤","description":"<p>$u{甘草}$w{二两 (炙)}  、$u{ 芒硝}$w{半斤}  、$u{大黄}$w{四两 (酒洗)}   。</p>\n<p></p>\n<p>         右三味，以水三升，煮二物至一升，去滓，纳芒硝，更上微火一二沸，温顿服之。</p>\n<p></p>\n<p>$a{桂版。伤寒论}$m{辨阳明病脉证并治}及$m{伤寒例第四} $n{芒硝}用量均为$q{半斤}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":5,"yaoCount":3,"drinkNum":1,"yaoList":["大黄","甘草","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"J7mL6gla0C0","amount":"半升","weight":null,"suffix":"","showName":"芒硝","extraProcess":""},{"yaoId":null,"amount":"二两","weight":null,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"To31b37bc6Z","amount":"四两、酒洗","weight":null,"suffix":"","showName":"大黄","extraProcess":""}]}}', '2024-12-07T06:20:08.000Z', '2024-12-07T06:20:08.000Z', '2024-12-07T06:20:08.000Z', '$u{甘草}$w{二两 (炙)} 、$u{ 芒硝}$w{半斤} 、$u{大黄}$w{四两 (酒洗)} 。 右三味，以水三升，煮二物至一升，去滓，纳芒硝，更上微火一二沸，温顿服之。 $a{桂版。伤寒论}$m{辨阳明病脉证并治}及$m{伤寒例第四} $n{芒硝}用量均为$q{半斤}', '2024-12-07T06:20:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2sQthsKIoUB', 1, '{"title":"小柴胡汤","description":"<p>$u{柴胡}$w{半斤}    $u{黄芩}    $u{人参}    $u{甘草}$w{炙}    $u{生姜}$w{各三两、切、}    $u{大枣}$w{十三枚、擘}  $u{半夏}$w{半升、洗、}</p>\n<p></p>\n<p>       右七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。另$a{伤寒例第四卷:小柴胡汤方 $m{大枣用量}$w{十二枚、擘} }  </p>\n<p></p>\n<p>         若胸中烦而不呕者，去 $u{半夏}、 $u{人参}，加 $u{栝蒌实}$w{一枚}。</p>\n<p>         若渴，去 $u{半夏}，加 $u{人参}合前成四两半， $u{栝蒌根}$w{四两}。</p>\n<p>         若腹中痛者，去 $u{黄芩}，加 $u{芍药}$w{三两}。</p>\n<p>         若胁下痞鞕，去 $u{大枣}，加 $u{牡蛎}$w{四两}。</p>\n<p>         若心下悸，小便不利者，去 $u{黄芩}，加 $u{茯苓}$w{四两}。</p>\n<p>         若不渴，外有微热者，去 $u{人参}，加 $u{桂枝}$w{三两}，温覆取微汗愈。</p>\n<p>         若咳者，去 $u{人参}、 $u{大枣}，加 $u{五味子}$w{半升}，去 $u{生姜}，加 $u{干姜}$w{二两}。</p>\n<p></p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":6,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","黄芩","人参","甘草","生姜","大枣","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":"","showName":"半夏","extraProcess":""},{"yaoId":"JZ9gTmGblYB","amount":"二十枚","weight":null,"suffix":"","showName":"大枣","extraProcess":""},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":null,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":null,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":null,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":null,"suffix":"","showName":"柴胡","extraProcess":"切"}]}}', '2024-12-07T06:37:19.000Z', '2024-12-07T06:37:19.000Z', '2024-12-07T06:37:19.000Z', '$u{柴胡}$w{半斤} $u{黄芩} $u{人参} $u{甘草}$w{炙} $u{生姜}$w{各三两、切、} $u{大枣}$w{十三枚、擘} $u{半夏}$w{半升、洗、} 右七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。另$a{伤寒例第四卷:小柴胡汤方 $m{大枣用量}$w{十二枚、擘} } 若胸中烦而不呕者，去 $u{半夏}、 $u{人参}，加 $u{栝蒌实}$w{一枚}。 若渴，去 $u{半夏}，加 $u{人参}合前成四两半， $u{栝蒌根}$w{四两}。 若腹中痛者，去 $u{黄芩}，加 $u{芍药}$w{三两}。 若胁下痞鞕，去 $u{大枣}，加 $u{牡蛎}$w{四两}。 若心下悸，小便不利者，去 $u{黄芩}，加 $u{茯苓}$w{四两}。 若不渴，外有微热者，去 $u{人参}，加 $u{桂枝}$w{三两}，温覆取微汗愈。 若咳者，去 $u{人参}、 $u{大枣}，加 $u{五味子}$w{半升}，去 $u{生姜}，加 $u{干姜}$w{二两}。', '2024-12-07T06:37:19.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1v9X61dngfU', 1, '{"title":"大柴胡汤","description":"<p>$u{柴胡}$w{半斤}    $u{黄芩}$w{三两}    $u{芍药}$w{三两}    $u{半夏}$w{半升(洗)}    $u{生姜}$w{五两、切}    $u{枳实}$w{四枚、炙}    $u{大枣}$w{十二枚、劈} $u{大黄}$w{二两}</p>\n<p></p>\n<p>\t右八味，以水一斗二升，煮取六升，去滓，再煎，温服二升，日三服。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":7,"yaoCount":8,"drinkNum":3,"yaoList":["柴胡","黄芩","芍药","半夏","生姜","枳实","大枣","大黄"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"二两","weight":null,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"二十枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"FRaBwjHoVui","amount":"四枚","weight":null,"suffix":"","showName":"枳实","extraProcess":"炙"},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":"","showName":"半夏","extraProcess":""},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":null,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":null,"suffix":"","showName":"柴胡","extraProcess":"切"}]}}', '2024-12-07T06:47:33.000Z', '2024-12-07T06:47:33.000Z', '2024-12-07T06:47:33.000Z', '$u{柴胡}$w{半斤} $u{黄芩}$w{三两} $u{芍药}$w{三两} $u{半夏}$w{半升(洗)} $u{生姜}$w{五两、切} $u{枳实}$w{四枚、炙} $u{大枣}$w{十二枚、劈} $u{大黄}$w{二两} 右八味，以水一斗二升，煮取六升，去滓，再煎，温服二升，日三服。', '2024-12-07T06:47:33.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
