INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2L7ueS1KIGI', 1, '{"title":"附子细辛黄连黄芩汤","description":"<p>$u{附子}$w{大者一枚（炮去皮破八片）} $u{细辛}$w{二两} $u{黄连}$w{四两} $u{黄芩}$w{二两}</p>\n<p>右四味，以水六升，煮取三升，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":9,"yaoCount":4,"drinkNum":3,"yaoList":["附子","细辛","黄连","黄芩"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"大者一枚（炮去皮破八片）","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"二两","weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"5GP5Zyu6577","amount":"四两","weight":null,"suffix":null,"showName":"黄连","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"二两","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null}]}}', '2024-12-07T07:00:10.000Z', '2024-12-07T07:00:10.000Z', '2024-12-07T07:00:10.000Z', '$u{附子}$w{大者一枚（炮去皮破八片）} $u{细辛}$w{二两} $u{黄连}$w{四两} $u{黄芩}$w{二两} 右四味，以水六升，煮取三升，温服一升，日三服。', '2024-12-07T07:00:10.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cE0XVGxhvCz', 1, '{"title":"乌梅丸","description":"<p>$u{乌梅}$w{三百枚}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{十六两}，$u{当归}$w{四两}，$u{附子}$w{六两，炮去皮}，$u{蜀椒}$w{四两、出汗}，$u{桂枝}$w{六两、去皮}，$u{人参}$w{六两}，$u{黄柏}$w{六两}</p>\n<p></p>\n<p>\t$s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷，滑物，臭食等。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":10,"yaoCount":10,"drinkNum":30,"yaoList":["乌梅","细辛","干姜","黄连","当归","附子","蜀椒","桂枝","人参","黄柏"],"fangList":[],"fangYaoList":[{"yaoId":"ld2CqoYXh1L","amount":"三百枚","weight":null,"suffix":null,"showName":"乌梅","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"六两","weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"十两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"5GP5Zyu6577","amount":"十六两","weight":null,"suffix":null,"showName":"黄连","extraProcess":null},{"yaoId":"JFnirDnffR9","amount":"四两","weight":null,"suffix":null,"showName":"当归","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"六两，炮去皮","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"03dIYYkyQRn","amount":"四两、出汗","weight":null,"suffix":null,"showName":"蜀椒","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"六两、去皮","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"六两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"Z5xEswEFq4S","amount":"六两","weight":null,"suffix":null,"showName":"黄柏","extraProcess":null}]}}', '2024-12-07T07:08:47.000Z', '2024-12-07T07:08:47.000Z', '2024-12-07T07:08:47.000Z', '$u{乌梅}$w{三百枚}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{十六两}，$u{当归}$w{四两}，$u{附子}$w{六两，炮去皮}，$u{蜀椒}$w{四两、出汗}，$u{桂枝}$w{六两、去皮}，$u{人参}$w{六两}，$u{黄柏}$w{六两} $s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷，滑物，臭食等。', '2024-12-07T07:08:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
