INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xCuQLhk7jds', 1, '{"title":"大青龙汤加附子","description":"<p>$u{麻黄}$w{六两（去节）} $u{桂枝}$w{二两（去皮）}$u{ 甘草}$w{二两（炙）} $u{杏仁}$w{四十枚（去皮尖）} $u{生姜}$w{三两（切）} $u{大枣}$w{十枚（劈）} $u{石膏}$w{如鸡子大 }$u{附子}$w{一枚（炮去皮破八片）}</p>\n<p></p>\n<p>       右八味，以水九升，先煮麻黄减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，取微似汗，汗出多者温粉粉之，一服汗者，停后服；若复服汗多亡阳，遂虚，恶风烦躁不得眠也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":12,"yaoCount":8,"drinkNum":1,"yaoList":["麻黄","桂枝","甘草","杏仁","生姜","大枣","石膏","附子"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两（去节）","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"四十枚（去皮尖）","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"如鸡子大","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚（炮去皮破八片）","weight":null,"suffix":null,"showName":"附子","extraProcess":null}]}}', '2024-12-07T07:15:47.000Z', '2024-12-07T07:15:47.000Z', '2024-12-07T07:15:47.000Z', '$u{麻黄}$w{六两（去节）} $u{桂枝}$w{二两（去皮）}$u{ 甘草}$w{二两（炙）} $u{杏仁}$w{四十枚（去皮尖）} $u{生姜}$w{三两（切）} $u{大枣}$w{十枚（劈）} $u{石膏}$w{如鸡子大 }$u{附子}$w{一枚（炮去皮破八片）} 右八味，以水九升，先煮麻黄减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，取微似汗，汗出多者温粉粉之，一服汗者，停后服；若复服汗多亡阳，遂虚，恶风烦躁不得眠也。', '2024-12-07T07:15:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
