INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kMEnfz56sBx', 1, '{"title":"百合地黄牡丹皮半夏茯苓汤","description":"<p>$u{百合}$w{七枚（劈）}、$u{地黄汁}$w{一升}、$u{牡丹皮}$w{六两}、$u{半夏}$w{一升}、$u{茯苓}$w{四两}。</p>\n<p></p>\n<p>        右五味，先以水洗百合，渍一宿，当白沫出，去其水，别以水二升，煮取一升，去滓，别以泉水四升，煮三味，取二升，去滓，纳地黄汁，与百合汁，更上火，令沸，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":30,"yaoCount":5,"drinkNum":3,"yaoList":["百合","地黄汁","牡丹皮","半夏","茯苓"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚（劈）","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":null,"amount":"一升","weight":null,"suffix":null,"showName":"地黄汁","extraProcess":null},{"yaoId":"nP2w4ZP4Yic","amount":"六两","weight":null,"suffix":null,"showName":"牡丹皮","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"一升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"四两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null}]}}', '2024-12-07T09:10:02.000Z', '2024-12-07T09:10:02.000Z', '2024-12-07T09:10:02.000Z', '$u{百合}$w{七枚（劈）}、$u{地黄汁}$w{一升}、$u{牡丹皮}$w{六两}、$u{半夏}$w{一升}、$u{茯苓}$w{四两}。 右五味，先以水洗百合，渍一宿，当白沫出，去其水，别以水二升，煮取一升，去滓，别以泉水四升，煮三味，取二升，去滓，纳地黄汁，与百合汁，更上火，令沸，温服一升，日三服。', '2024-12-07T09:10:02.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
