INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JMlfU5aVt5n', 1, '{"title":"黄连石膏半夏甘草汤","description":"<p>$u{黄连}$w{一两 }，$u{石膏}$w{一斤碎（棉裹）}，$u{ 半夏}$w{半升（洗） }，$u{甘草}$w{三两}</p>\n<p></p>\n<p>      右四味，以水六升，煮取三升，去滓，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":45,"yaoCount":3,"drinkNum":3,"yaoList":["黄连","石膏","半夏","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"5GP5Zyu6577","amount":"一两","weight":null,"suffix":null,"showName":"黄连","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"一斤碎（棉裹）","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升（洗）","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-09T01:35:22.000Z', '2024-12-09T01:35:22.000Z', '2024-12-09T01:35:22.000Z', '$u{黄连}$w{一两 }，$u{石膏}$w{一斤碎（棉裹）}，$u{ 半夏}$w{半升（洗） }，$u{甘草}$w{三两} 右四味，以水六升，煮取三升，去滓，温服一升，日三服。', '2024-12-09T01:35:22.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
