INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vMYj1BcSs0e', 1, '{"title":"桂枝茯苓白术细辛汤","description":"<p>$u{桂枝}$w{三两 }，$u{茯苓}$w{四两 }，$u{白术}$w{三两 }，$u{细辛}$w{二两}</p>\n<p></p>\n<p>      右四味，以水六升，煮取二升，去滓，温服一升，日再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":48,"yaoCount":4,"drinkNum":2,"yaoList":["桂枝","茯苓","白术","细辛"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"四两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"二两","weight":null,"suffix":null,"showName":"细辛","extraProcess":null}]}}', '2024-12-09T01:47:37.000Z', '2024-12-09T01:47:37.000Z', '2024-12-09T01:47:37.000Z', '$u{桂枝}$w{三两 }，$u{茯苓}$w{四两 }，$u{白术}$w{三两 }，$u{细辛}$w{二两} 右四味，以水六升，煮取二升，去滓，温服一升，日再服。', '2024-12-09T01:47:37.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JH0l37uJZ0r', 1, '{"title":"桂枝麻黄各半汤","description":"<p>即$f{桂枝汤}三合，$f{麻黄汤}三合，并为六合，顿服之，将息如$f{桂枝汤}法。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":49,"yaoCount":1,"drinkNum":1,"yaoList":[],"fangList":[],"fangYaoList":[]}}', '2024-12-09T01:54:21.000Z', '2024-12-09T01:54:21.000Z', '2024-12-09T01:54:21.000Z', '即$f{桂枝汤}三合，$f{麻黄汤}三合，并为六合，顿服之，将息如$f{桂枝汤}法。', '2024-12-09T01:54:21.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1l43ejWnPXB', 1, '{"title":"桂枝汤","description":"<p>$u{桂枝}$w{三两（去皮） }，$u{芍药}$w{三两 }，$u{甘草}$w{二两（炙） }，$u{生姜}$w{三两（切） }，$u{大枣}$w{十二枚（劈）}</p>\n<p></p>\n<p>        右五味，〖口父〗咀。以水七升，微火煮取三升，去滓，适寒温，服一升。服已须臾，啜热稀粥一升余，以助药力，温覆令一时许，遍身漐漐，微似有汗者益佳，不可令如水流漓，病必不除。若一服汗出病差，停后服，不必尽剂；若不汗，更服依前法；又不汗，后服小促其间，半日许，令三服尽；若病重者，一日一夜服，周时观之。服一剂尽，病证犹在者，更作服；若汗不出，乃服至二三剂。禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":50,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-09T01:56:59.000Z', '2024-12-09T01:56:59.000Z', '2024-12-09T01:56:59.000Z', '$u{桂枝}$w{三两（去皮） }，$u{芍药}$w{三两 }，$u{甘草}$w{二两（炙） }，$u{生姜}$w{三两（切） }，$u{大枣}$w{十二枚（劈）} 右五味，〖口父〗咀。以水七升，微火煮取三升，去滓，适寒温，服一升。服已须臾，啜热稀粥一升余，以助药力，温覆令一时许，遍身漐漐，微似有汗者益佳，不可令如水流漓，病必不除。若一服汗出病差，停后服，不必尽剂；若不汗，更服依前法；又不汗，后服小促其间，半日许，令三服尽；若病重者，一日一夜服，周时观之。服一剂尽，病证犹在者，更作服；若汗不出，乃服至二三剂。禁生冷、粘滑、肉面、五辛、酒酪、臭恶等物。', '2024-12-09T01:56:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0qd3R2sdvY5', 1, '{"title":"大青龙汤","description":"<p>$u{麻黄}$w{六两（去节） }、$u{桂枝}$w{二两（去皮） }、$u{甘草}$w{二两（炙） }、$u{杏仁}$w{四十枚（去皮尖） }、$u{生姜}$w{三两（切） }、$u{大枣}$w{十二枚（劈） }、$u{石膏}$w{如鸡子大（碎） }。</p>\n<p></p>\n<p>      右七味，以水九升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，取微似汗，汗多者，温粉粉之。一服汗出停后服。若复服汗多亡阳，遂虚，恶风烦躁，不得眠也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":51,"yaoCount":7,"drinkNum":3,"yaoList":["麻黄","桂枝","甘草","杏仁","生姜","大枣","石膏"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两（去节）","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"四十枚（去皮尖）","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"如鸡子大（碎）","weight":null,"suffix":null,"showName":"石膏","extraProcess":null}]}}', '2024-12-09T01:58:10.000Z', '2024-12-09T01:58:10.000Z', '2024-12-09T01:58:10.000Z', '$u{麻黄}$w{六两（去节） }、$u{桂枝}$w{二两（去皮） }、$u{甘草}$w{二两（炙） }、$u{杏仁}$w{四十枚（去皮尖） }、$u{生姜}$w{三两（切） }、$u{大枣}$w{十二枚（劈） }、$u{石膏}$w{如鸡子大（碎） }。 右七味，以水九升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，取微似汗，汗多者，温粉粉之。一服汗出停后服。若复服汗多亡阳，遂虚，恶风烦躁，不得眠也。', '2024-12-09T01:58:10.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lzFUDdP49mn', 1, '{"title":"白术茯苓厚朴汤","description":"<p>$u{白术}$w{三两 }，$u{茯苓}$w{四两 }，$u{厚朴}$w{二两（炙去皮）}，</p>\n<p>      右三味，以水五升，煮取一升五合，去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":52,"yaoCount":3,"drinkNum":2,"yaoList":["白术","茯苓","厚朴"],"fangList":[],"fangYaoList":[{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"四两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"8714SID7nWu","amount":"二两（炙去皮）","weight":null,"suffix":null,"showName":"厚朴","extraProcess":null}]}}', '2024-12-09T02:01:26.000Z', '2024-12-09T02:01:26.000Z', '2024-12-09T02:01:26.000Z', '$u{白术}$w{三两 }，$u{茯苓}$w{四两 }，$u{厚朴}$w{二两（炙去皮）}， 右三味，以水五升，煮取一升五合，去滓，分温再服。', '2024-12-09T02:01:26.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
