INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GU7lxAb115F', 1, '{"title":"理中汤","description":"<p>$u{人参}$w{三两 }，$u{干姜}$w{三两 }，$u{白术}$w{三两 }，$u{甘草}$w{三两（炙）}</p>\n<p></p>\n<p>   右四味，以水八升，煮取三升，去滓，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":54,"yaoCount":4,"drinkNum":3,"yaoList":["人参","干姜","白术","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-09T02:04:18.000Z', '2024-12-09T02:04:18.000Z', '2024-12-09T02:04:18.000Z', '$u{人参}$w{三两 }，$u{干姜}$w{三两 }，$u{白术}$w{三两 }，$u{甘草}$w{三两（炙）} 右四味，以水八升，煮取三升，去滓，温服一升，日三服。', '2024-12-09T02:04:18.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vM237Qrpjn1', 1, '{"title":"小青龙汤","description":"<p>$u{麻黄}$w{三两（去节） }，$u{ 芍药}$w{三两  }，$u{细辛}$w{三两  }，$u{桂枝}$w{三两（去皮）  }，$u{干姜}$w{三两  }，$u{半夏}$w{半升（洗） }，$u{ 甘草}$w{三两  }，$u{五味子}$w{半升}</p>\n<p></p>\n<p>      右八味，以水一斗，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升。日三服。</p>\n<p></p>\n<p>       若渴去$u{半夏}，加$u{栝蒌根}$w{三两}；</p>\n<p>       若微利，若噎者，去$u{麻黄}，加$u{附子}$w{一枚}；</p>\n<p>       若小便不利，少服满者，去$u{麻黄}，加$u{茯苓}$w{四两}；</p>\n<p>       若喘者，加$u{杏仁}$w{半升（去皮尖）}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":55,"yaoCount":8,"drinkNum":3,"yaoList":["麻黄","芍药","细辛","桂枝","干姜","半夏","甘草","五味子"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两（去节）","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"三两","weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升（洗）","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":null,"suffix":null,"showName":"五味子","extraProcess":null}]}}', '2024-12-09T02:06:11.000Z', '2024-12-09T02:06:11.000Z', '2024-12-09T02:06:11.000Z', '$u{麻黄}$w{三两（去节） }，$u{ 芍药}$w{三两 }，$u{细辛}$w{三两 }，$u{桂枝}$w{三两（去皮） }，$u{干姜}$w{三两 }，$u{半夏}$w{半升（洗） }，$u{ 甘草}$w{三两 }，$u{五味子}$w{半升} 右八味，以水一斗，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升。日三服。 若渴去$u{半夏}，加$u{栝蒌根}$w{三两}； 若微利，若噎者，去$u{麻黄}，加$u{附子}$w{一枚}； 若小便不利，少服满者，去$u{麻黄}，加$u{茯苓}$w{四两}； 若喘者，加$u{杏仁}$w{半升（去皮尖）}。', '2024-12-09T02:06:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y90GGyEFksm', 1, '{"title":"五苓散","description":"<p>$u{猪苓}$w{十八铢（去皮）  }，$u{泽泻}$w{一两六铢  }，$u{茯苓}$w{十八铢  }，$u{桂枝}$w{半两（去皮）  }，$u{白术}$w{十八铢 }</p>\n<p></p>\n<p>     右五味，捣为散，以白饮和服方寸匙，日三服，多饮暖水，汗出愈。</p>\n<p></p>\n<p>    另 $a{伤寒论.桂版-辨太阳病脉证并治下}发黄者，加$u{茵陈蒿}}$w{十分}。</p>\n<p></p>\n<p>        $a{伤寒论.桂版-辨阳明病脉证并治}诸黄家，但利其小便，五苓散加茵陈蒿主之；$f{五苓散}加$u{茵陈蒿}$w{十分}同末)。</p>\n<p></p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":56,"yaoCount":5,"drinkNum":3,"yaoList":["猪苓","泽泻","茯苓","桂枝","白术"],"fangList":[],"fangYaoList":[{"yaoId":"VBp4qtisnQR","amount":"十八铢（去皮）","weight":null,"suffix":null,"showName":"猪苓","extraProcess":null},{"yaoId":"TvTXZli2dE7","amount":"一两六铢","weight":null,"suffix":null,"showName":"泽泻","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"十八铢","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"半两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"十八铢","weight":null,"suffix":null,"showName":"白术","extraProcess":null}]}}', '2024-12-09T02:08:22.000Z', '2024-12-09T02:08:22.000Z', '2024-12-09T02:08:22.000Z', '$u{猪苓}$w{十八铢（去皮） }，$u{泽泻}$w{一两六铢 }，$u{茯苓}$w{十八铢 }，$u{桂枝}$w{半两（去皮） }，$u{白术}$w{十八铢 } 右五味，捣为散，以白饮和服方寸匙，日三服，多饮暖水，汗出愈。 另 $a{伤寒论.桂版-辨太阳病脉证并治下}发黄者，加$u{茵陈蒿}}$w{十分}。 $a{伤寒论.桂版-辨阳明病脉证并治}诸黄家，但利其小便，五苓散加茵陈蒿主之；$f{五苓散}加$u{茵陈蒿}$w{十分}同末)。', '2024-12-09T02:08:22.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
