INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BK7AjK6vQm1', 1, '{"title":"麻黄加术汤","description":"<p>$u{麻黄}$w{三两（去节） }，$u{桂枝}$w{二两（去皮） }，$u{甘草}$w{一两（炙）  }，$u{白术}$w{四两  }，$u{杏仁七}$w{十个（去皮尖）}</p>\n<p></p>\n<p>      右五味，以水九升，先煮麻黄，减二升，去上沫，纳诸药，煮取二升半，去滓，温服八合，覆取微汗，不得汉再服，得汗，停后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":58,"yaoCount":5,"drinkNum":3,"yaoList":["麻黄","桂枝","甘草","白术","杏仁七"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两（去节）","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"四两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":null,"amount":"十个（去皮尖）","weight":null,"suffix":null,"showName":"杏仁七","extraProcess":null}]}}', '2024-12-09T02:38:09.000Z', '2024-12-09T02:38:09.000Z', '2024-12-09T02:38:09.000Z', '$u{麻黄}$w{三两（去节） }，$u{桂枝}$w{二两（去皮） }，$u{甘草}$w{一两（炙） }，$u{白术}$w{四两 }，$u{杏仁七}$w{十个（去皮尖）} 右五味，以水九升，先煮麻黄，减二升，去上沫，纳诸药，煮取二升半，去滓，温服八合，覆取微汗，不得汉再服，得汗，停后服。', '2024-12-09T02:38:09.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Z3qtDPnX3t', 1, '{"title":"麻黄杏仁薏苡甘草汤","description":"<p>$u{麻黄}$w{一两  }，$u{杏仁}$w{二十枚（去皮尖） }，$u{ 薏苡}$w{一两  }，$u{甘草}$w{一两（炙） }，</p>\n<p></p>\n<p>      右四味，以水六升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":59,"yaoCount":4,"drinkNum":3,"yaoList":["麻黄","杏仁","薏苡","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"一两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"二十枚（去皮尖）","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null},{"yaoId":null,"amount":"一两","weight":null,"suffix":null,"showName":"薏苡","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-09T02:41:21.000Z', '2024-12-09T02:41:21.000Z', '2024-12-09T02:41:21.000Z', '$u{麻黄}$w{一两 }，$u{杏仁}$w{二十枚（去皮尖） }，$u{ 薏苡}$w{一两 }，$u{甘草}$w{一两（炙） }， 右四味，以水六升，先煮麻黄，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。', '2024-12-09T02:41:21.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yhN0MZRzshi', 1, '{"title":"防己黄芪汤","description":"<p>$u{ 防己}$w{二两 }，$u{ 甘草}$w{一两（炙）  }，$u{白术}$w{一两  }，$u{黄芪}$w{二两  }，$u{生姜}$w{一两 }，$u{ 大枣}$w{十二枚（劈）}</p>\n<p></p>\n<p>       右六味，以水一斗，煮取五升，去滓，再煎取三升，温服一升，日三服；喘者加麻黄五分；胃中不和者，加芍药三分；气上冲者，加桂枝三分；下有陈寒者，加细辛三分；服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕之，温令有微汗差。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":60,"yaoCount":6,"drinkNum":3,"yaoList":["防己","甘草","白术","黄芪","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"M9HezPeSGkC","amount":"二两","weight":null,"suffix":null,"showName":"防己","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"一两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"i7j1zMcc48a","amount":"二两","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"一两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-09T02:44:15.000Z', '2024-12-09T02:44:15.000Z', '2024-12-09T02:44:15.000Z', '$u{ 防己}$w{二两 }，$u{ 甘草}$w{一两（炙） }，$u{白术}$w{一两 }，$u{黄芪}$w{二两 }，$u{生姜}$w{一两 }，$u{ 大枣}$w{十二枚（劈）} 右六味，以水一斗，煮取五升，去滓，再煎取三升，温服一升，日三服；喘者加麻黄五分；胃中不和者，加芍药三分；气上冲者，加桂枝三分；下有陈寒者，加细辛三分；服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕之，温令有微汗差。', '2024-12-09T02:44:15.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TMQ368oGhH0', 1, '{"title":"桂枝附子汤","description":"<p>$u{桂枝}$w{四两（去皮） }，$u{ 附子}$w{二枚（炮）  }，$u{甘草}$w{二两（炙）  }，$u{生姜}$w{三两（切）  }，$u{大枣}$w{十二枚（劈） }，</p>\n<p></p>\n<p>      右五味，以水六升，煮取三升，去滓，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":61,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","附子","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"四两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"二枚（炮）","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-09T02:46:14.000Z', '2024-12-09T02:46:14.000Z', '2024-12-09T02:46:14.000Z', '$u{桂枝}$w{四两（去皮） }，$u{ 附子}$w{二枚（炮） }，$u{甘草}$w{二两（炙） }，$u{生姜}$w{三两（切） }，$u{大枣}$w{十二枚（劈） }， 右五味，以水六升，煮取三升，去滓，分温三服。', '2024-12-09T02:46:14.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d9ZIvGl7AUn', 1, '{"title":"白术附子汤","description":"<p>$u{白术}$w{一两 }，$u{附子}$w{一枚（炮）}，$u{ 甘草}$w{二两（炙）}，$u{ 生姜}$w{一两半 }，$u{大枣}$w{六枚（劈）}</p>\n<p></p>\n<p>     右五味，以水三升，煮取一升，去滓，分温三服，一服觉身痹，半日许再服，三服都尽，其人如冒状，勿怪，即术附并走皮中，逐水气，未得除耳。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":62,"yaoCount":5,"drinkNum":3,"yaoList":["白术","附子","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"UIYZOmiE2xW","amount":"一两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚（炮）","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"一两半","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"六枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-09T02:48:13.000Z', '2024-12-09T02:48:13.000Z', '2024-12-09T02:48:13.000Z', '$u{白术}$w{一两 }，$u{附子}$w{一枚（炮）}，$u{ 甘草}$w{二两（炙）}，$u{ 生姜}$w{一两半 }，$u{大枣}$w{六枚（劈）} 右五味，以水三升，煮取一升，去滓，分温三服，一服觉身痹，半日许再服，三服都尽，其人如冒状，勿怪，即术附并走皮中，逐水气，未得除耳。', '2024-12-09T02:48:13.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ELwoJWqPoHc', 1, '{"title":"甘草附子汤","description":"<p>$u{甘草}$w{二两（炙） }，$u{附子}$w{二枚（炮去皮） }，$u{白术}$w{二两 }，$u{桂枝}$w{四两}</p>\n<p></p>\n<p>      右四味，以水六升，煮取三升，去滓，温服一升，日三服。初服得微汗则解；能食，汗出，复烦者，服五合；恐一升多者，服六七合为佳。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":63,"yaoCount":4,"drinkNum":3,"yaoList":["甘草","附子","白术","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"二枚（炮去皮）","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"四两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null}]}}', '2024-12-09T02:50:11.000Z', '2024-12-09T02:50:11.000Z', '2024-12-09T02:50:11.000Z', '$u{甘草}$w{二两（炙） }，$u{附子}$w{二枚（炮去皮） }，$u{白术}$w{二两 }，$u{桂枝}$w{四两} 右四味，以水六升，煮取三升，去滓，温服一升，日三服。初服得微汗则解；能食，汗出，复烦者，服五合；恐一升多者，服六七合为佳。', '2024-12-09T02:50:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
