INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pfN8OpNAv2L', 1, '{"title":"麻仁白蜜煎","description":"<p>$u{麻仁}$w{一升  }，$u{白蜜}$w{六合 }.</p>\n<p></p>\n<p>       右二味，以水四升，先煮麻仁，取一升五合，去滓，纳蜜，微沸，和合，令小冷，顿服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":65,"yaoCount":2,"drinkNum":2,"yaoList":["麻仁","白蜜"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"一升","weight":null,"suffix":null,"showName":"麻仁","extraProcess":null},{"yaoId":"IHSagd4ikNY","amount":"六合","weight":null,"suffix":null,"showName":"白蜜","extraProcess":null}]}}', '2024-12-09T03:06:22.000Z', '2024-12-09T03:06:22.000Z', '2024-12-09T03:06:22.000Z', '$u{麻仁}$w{一升 }，$u{白蜜}$w{六合 }. 右二味，以水四升，先煮麻仁，取一升五合，去滓，纳蜜，微沸，和合，令小冷，顿服之。', '2024-12-09T03:06:22.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
