INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I3u3HSaNYEG', 1, '{"title":"通脉四逆汤","description":"<p>$u{甘草}$w{二两（炙） }、$u{附子}$w{大者一枚（生用破） }、$u{干姜}$w{三两 }、$u{人参}$w{二两 }。</p>\n<p></p>\n<p>       右四味，以水三生态煮取一升二合，去滓，分温再服。</p>\n<p></p>\n<p> 另$a{桂版。伤赛论-辨少阴病脉证并治}</p>\n<p>      其脉即出者愈。</p>\n<p>     面色赤者，加$u{葱}$w{九茎}；腹中痛者，去$u{葱}，加$u{芍药}$w{二两}；</p>\n<p>     呕者，加$u{生姜}$w{二两}；</p>\n<p>     咽痛者，去$u{芍药}，加$u{桔梗}$w{一两}；</p>\n<p>     利止，脉不出者，去$u{桔梗}，加$u{人参}$w{二两}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":80,"yaoCount":4,"drinkNum":2,"yaoList":["甘草","附子","干姜","人参"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"大者一枚（生用破）","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":null,"suffix":null,"showName":"人参","extraProcess":null}]}}', '2024-12-09T08:00:11.000Z', '2024-12-09T08:00:11.000Z', '2024-12-09T08:00:11.000Z', '$u{甘草}$w{二两（炙） }、$u{附子}$w{大者一枚（生用破） }、$u{干姜}$w{三两 }、$u{人参}$w{二两 }。 右四味，以水三生态煮取一升二合，去滓，分温再服。 另$a{桂版。伤赛论-辨少阴病脉证并治} 其脉即出者愈。 面色赤者，加$u{葱}$w{九茎}；腹中痛者，去$u{葱}，加$u{芍药}$w{二两}； 呕者，加$u{生姜}$w{二两}； 咽痛者，去$u{芍药}，加$u{桔梗}$w{一两}； 利止，脉不出者，去$u{桔梗}，加$u{人参}$w{二两}。', '2024-12-09T08:00:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
