INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KFOXAoyHz62', 1, '{"title":"葛根汤","description":"<p>$u{葛根}$w{四两}、$u{麻黄}$w{三两（去节）}、$u{桂枝}$w{二两（去皮）}、$u{芍药}$w{二两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}。</p>\n<p></p>\n<p>     右七味，以水一斗，先煮麻黄葛根，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，复取微似汗，不须啜粥，余如桂枝法将息及禁忌，诸汤皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":93,"yaoCount":7,"drinkNum":3,"yaoList":["葛根","麻黄","桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"MzvPguhXJ5G","amount":"四两","weight":null,"suffix":null,"showName":"葛根","extraProcess":null},{"yaoId":"nxz0hvgpJJf","amount":"三两（去节）","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"二两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-11T04:00:59.000Z', '2024-12-11T04:00:59.000Z', '2024-12-11T04:00:59.000Z', '$u{葛根}$w{四两}、$u{麻黄}$w{三两（去节）}、$u{桂枝}$w{二两（去皮）}、$u{芍药}$w{二两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}。 右七味，以水一斗，先煮麻黄葛根，减二升，去上沫，纳诸药，煮取三升，去滓，温服一升，复取微似汗，不须啜粥，余如桂枝法将息及禁忌，诸汤皆仿此。', '2024-12-11T04:00:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
