INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ZBoUvvuKL8', 1, '{"title":"茯苓桂枝甘草大枣汤","description":"<p>$u{茯苓}$w{半斤}、$u{桂枝}$w{四两}、$u{甘草}$w{二两（炙）}、$u{大枣}$w{十五枚（劈）}。</p>\n<p></p>\n<p>    右四味，以甘澜水一斗，先煮茯苓减二升，纳诸药，煮取三升，去滓，温服一升，日三服。</p>\n<p></p>\n<p>作甘澜水法，取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":100,"yaoCount":4,"drinkNum":3,"yaoList":["茯苓","桂枝","甘草","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"半斤","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"四两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十五枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-11T06:44:39.000Z', '2024-12-11T06:44:39.000Z', '2024-12-11T06:44:39.000Z', '$u{茯苓}$w{半斤}、$u{桂枝}$w{四两}、$u{甘草}$w{二两（炙）}、$u{大枣}$w{十五枚（劈）}。 右四味，以甘澜水一斗，先煮茯苓减二升，纳诸药，煮取三升，去滓，温服一升，日三服。 作甘澜水法，取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。', '2024-12-11T06:44:39.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
