INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ljk4a6nBhz2', 1, '{"title":"栀子干姜汤","description":"<p>$u{栀子}$w{十四枚（劈） }、$u{生姜}$w{二两（切）}。</p>\n<p></p>\n<p>     右二味，以水三升半，煮取一升半，去滓，分温二服，进一服得吐者止后服。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":109,"yaoCount":2,"drinkNum":2,"yaoList":["栀子","生姜"],"fangList":[],"fangYaoList":[{"yaoId":"7fWzC6yB6Yy","amount":"十四枚（劈）","weight":null,"suffix":null,"showName":"栀子","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"二两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null}]}}', '2024-12-11T07:09:35.000Z', '2024-12-11T07:09:35.000Z', '2024-12-11T07:09:35.000Z', '$u{栀子}$w{十四枚（劈） }、$u{生姜}$w{二两（切）}。 右二味，以水三升半，煮取一升半，去滓，分温二服，进一服得吐者止后服。', '2024-12-11T07:09:35.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tZUBNsp6zOk', 1, '{"title":"栀子豉汤","description":"<p>$u{栀子}$w{十四枚（劈） }、$u{香豉}$w{四合（棉裹） }。</p>\n<p></p>\n<p>    右二味，以水四升，先煮栀子得二升半，纳豉煮取一升半，去滓，分为二服，温进一服，得吐者止后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":110,"yaoCount":2,"drinkNum":2,"yaoList":["栀子","香豉"],"fangList":[],"fangYaoList":[{"yaoId":"7fWzC6yB6Yy","amount":"十四枚（劈）","weight":null,"suffix":null,"showName":"栀子","extraProcess":null},{"yaoId":"sx4xviDfH00","amount":"四合（棉裹）","weight":null,"suffix":null,"showName":"香豉","extraProcess":null}]}}', '2024-12-11T07:11:34.000Z', '2024-12-11T07:11:34.000Z', '2024-12-11T07:11:34.000Z', '$u{栀子}$w{十四枚（劈） }、$u{香豉}$w{四合（棉裹） }。 右二味，以水四升，先煮栀子得二升半，纳豉煮取一升半，去滓，分为二服，温进一服，得吐者止后服。', '2024-12-11T07:11:34.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Vavw8zsJkp', 1, '{"title":"栀子厚朴枳实汤","description":"<p>$u{栀子}$w{十四枚（劈） }、$u{厚朴}$w{四两（炙去皮） }、$u{枳实}$w{四枚（水浸炙令黄） }。</p>\n<p></p>\n<p>      以上三味，以水三升半，煮取一升半，去滓，分二服。温进一服，得吐者止后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":111,"yaoCount":3,"drinkNum":2,"yaoList":["栀子","厚朴","枳实"],"fangList":[],"fangYaoList":[{"yaoId":"7fWzC6yB6Yy","amount":"十四枚（劈）","weight":null,"suffix":null,"showName":"栀子","extraProcess":null},{"yaoId":"8714SID7nWu","amount":"四两（炙去皮）","weight":null,"suffix":null,"showName":"厚朴","extraProcess":null},{"yaoId":"FRaBwjHoVui","amount":"四枚（水浸炙令黄）","weight":null,"suffix":null,"showName":"枳实","extraProcess":null}]}}', '2024-12-11T07:15:34.000Z', '2024-12-11T07:15:34.000Z', '2024-12-11T07:15:34.000Z', '$u{栀子}$w{十四枚（劈） }、$u{厚朴}$w{四两（炙去皮） }、$u{枳实}$w{四枚（水浸炙令黄） }。 以上三味，以水三升半，煮取一升半，去滓，分二服。温进一服，得吐者止后服。', '2024-12-11T07:15:34.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jSL0Yv4eNkW', 1, '{"title":"真武汤","description":"<p>$u{茯苓}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{三两（切）}、$u{白术}$w{二两}、$u{附子}$w{一枚（炮去皮破八片）}。</p>\n<p></p>\n<p>    右五味，要以水八升，煮取三升，去滓，温服七合，日三服。</p>\n<p>    若咳者，加$u{五味子}$w{半升}，$u{细辛$u{干姜}$w{各一两}；</p>\n<p>    若小便不利者，加$u{茯苓}$w{一两}；</p>\n<p>    若下利者，去$u{芍药}，加$u{干姜}$w{二两}；</p>\n<p>    若呕者，去$u{附子}，加$u{生姜}$w{足前成半斤}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":112,"yaoCount":5,"drinkNum":3,"yaoList":["茯苓","芍药","生姜","白术","附子"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚（炮去皮破八片）","weight":null,"suffix":null,"showName":"附子","extraProcess":null}]}}', '2024-12-11T07:18:00.000Z', '2024-12-11T07:18:00.000Z', '2024-12-11T07:18:00.000Z', '$u{茯苓}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{三两（切）}、$u{白术}$w{二两}、$u{附子}$w{一枚（炮去皮破八片）}。 右五味，要以水八升，煮取三升，去滓，温服七合，日三服。 若咳者，加$u{五味子}$w{半升}，$u{细辛$u{干姜}$w{各一两}； 若小便不利者，加$u{茯苓}$w{一两}； 若下利者，去$u{芍药}，加$u{干姜}$w{二两}； 若呕者，去$u{附子}，加$u{生姜}$w{足前成半斤}。', '2024-12-11T07:18:00.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4IOY4O6Fd21', 1, '{"title":"禹余粮丸","description":"<p>$u{禹余粮}$w{四两}、$u{人参}$w{三两}、$u{附子}$w{二枚}、$u{五味子}$w{三合}、$u{茯苓}$w{三两}、$u{干姜}$w{三两}。</p>\n<p></p>\n<p>     右六味，蜜为丸，如梧子大，每服二十丸。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":113,"yaoCount":6,"drinkNum":20,"yaoList":["禹余粮","人参","附子","五味子","茯苓","干姜"],"fangList":[],"fangYaoList":[{"yaoId":"o993hnzlGnH","amount":"四两","weight":null,"suffix":null,"showName":"禹余粮","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"二枚","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"C74sm5pJRdN","amount":"三合","weight":null,"suffix":null,"showName":"五味子","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null}]}}', '2024-12-11T07:21:41.000Z', '2024-12-11T07:21:41.000Z', '2024-12-11T07:21:41.000Z', '$u{禹余粮}$w{四两}、$u{人参}$w{三两}、$u{附子}$w{二枚}、$u{五味子}$w{三合}、$u{茯苓}$w{三两}、$u{干姜}$w{三两}。 右六味，蜜为丸，如梧子大，每服二十丸。', '2024-12-11T07:21:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iDxCZ3WgdYl', 1, '{"title":"小建中汤","description":"<p>$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}。</p>\n<p></p>\n<p>      右六味，以水七升，先煮五味取三升，去滓内饴更上微火消解，温服一升，日三服。呕家不可用，以甜故也。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":114,"yaoCount":6,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣","胶饴"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"六两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":null,"suffix":null,"showName":"胶饴","extraProcess":null}]}}', '2024-12-11T07:40:08.000Z', '2024-12-11T07:40:08.000Z', '2024-12-11T07:40:08.000Z', '$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}。 右六味，以水七升，先煮五味取三升，去滓内饴更上微火消解，温服一升，日三服。呕家不可用，以甜故也。', '2024-12-11T07:40:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7P5cMAEVIYR', 1, '{"title":"小陷胸汤","description":"<p>$u{黄连}$w{一两 }、$u{半夏}$w{半升 }、$u{括蒌实}$w{大者一枚 }</p>\n<p></p>\n<p>           右三味，以水六升，先煮括蒌取三升，纳诸药，煮取二升，去滓，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":115,"yaoCount":3,"drinkNum":3,"yaoList":["黄连","半夏","括蒌实"],"fangList":[],"fangYaoList":[{"yaoId":"5GP5Zyu6577","amount":"一两","weight":null,"suffix":null,"showName":"黄连","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":null,"amount":"大者一枚","weight":null,"suffix":null,"showName":"括蒌实","extraProcess":null}]}}', '2024-12-11T07:43:22.000Z', '2024-12-11T07:43:22.000Z', '2024-12-11T07:43:22.000Z', '$u{黄连}$w{一两 }、$u{半夏}$w{半升 }、$u{括蒌实}$w{大者一枚 } 右三味，以水六升，先煮括蒌取三升，纳诸药，煮取二升，去滓，分温三服。', '2024-12-11T07:43:22.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DxTEEoMvNsV', 1, '{"title":"柴胡加芒消汤","description":"<p>$u{柴胡}$w{二两十六铢 }、$u{黄芩}$w{一两 }、$u{人参}$w{一两 }、$u{甘草}$w{一两（炙） }、$u{生姜}$w{一两（切） }、$u{芒硝}$w{二两 }、$u{大枣}$w{四枚 }、$u{半夏}$w{二十铢 }。</p>\n<p></p>\n<p>     右八味，以水四升，煮取二升，去滓，纳芒硝，更煮微沸，分温再服，不解更作。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":116,"yaoCount":8,"drinkNum":2,"yaoList":["柴胡","黄芩","人参","甘草","生姜","芒硝","大枣","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"二两十六铢","weight":null,"suffix":null,"showName":"柴胡","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"一两","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"一两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"J7mL6gla0C0","amount":"二两","weight":null,"suffix":null,"showName":"芒硝","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"四枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"二十铢","weight":null,"suffix":null,"showName":"半夏","extraProcess":null}]}}', '2024-12-11T07:45:59.000Z', '2024-12-11T07:45:59.000Z', '2024-12-11T07:45:59.000Z', '$u{柴胡}$w{二两十六铢 }、$u{黄芩}$w{一两 }、$u{人参}$w{一两 }、$u{甘草}$w{一两（炙） }、$u{生姜}$w{一两（切） }、$u{芒硝}$w{二两 }、$u{大枣}$w{四枚 }、$u{半夏}$w{二十铢 }。 右八味，以水四升，煮取二升，去滓，纳芒硝，更煮微沸，分温再服，不解更作。', '2024-12-11T07:45:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0eWZ4bkB2vN', 1, '{"title":"桃仁承气汤","description":"<p>$u{桃仁}$w{五十个（去皮尖） }、$u{大黄}$w{四两 }、$u{桂枝}$w{二两 }、$u{甘草}$w{二两（炙） }、$u{芒硝}$w{二两}。</p>\n<p></p>\n<p>      右五味，以水七升，煮四味，取二升，去滓，纳芒硝，更上火微沸。下火，先食温服五合，日三服，当微利。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":117,"yaoCount":5,"drinkNum":3,"yaoList":["桃仁","大黄","桂枝","甘草","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"k2cI79Wat6h","amount":"五十个（去皮尖）","weight":null,"suffix":null,"showName":"桃仁","extraProcess":null},{"yaoId":"To31b37bc6Z","amount":"四两","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"J7mL6gla0C0","amount":"二两","weight":null,"suffix":null,"showName":"芒硝","extraProcess":null}]}}', '2024-12-11T07:48:27.000Z', '2024-12-11T07:48:27.000Z', '2024-12-11T07:48:27.000Z', '$u{桃仁}$w{五十个（去皮尖） }、$u{大黄}$w{四两 }、$u{桂枝}$w{二两 }、$u{甘草}$w{二两（炙） }、$u{芒硝}$w{二两}。 右五味，以水七升，煮四味，取二升，去滓，纳芒硝，更上火微沸。下火，先食温服五合，日三服，当微利。', '2024-12-11T07:48:27.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zPAxELhl5vC', 1, '{"title":"柴胡加龙骨牡蛎汤","description":"<p>$u{柴胡}$w{四两 }、$u{龙骨}$w{一两半 }、$u{黄芩}$w{一两半 }、$u{生姜}$w{一两半 }、$u{人参}$w{一两半 }、$u{桂枝}$w{一两半（去皮） }、$u{茯苓}$w{一两半 }、$u{半夏}$w{二合半 }、$u{大黄}$w{二两 }、$u{牡蛎}$w{一两半 }、$u{大枣}$w{六枚（劈） }、$u{铅丹}$w{一两半}。</p>\n<p></p>\n<p>       右十二味，以水八升，煮取四升，纳大黄切如棋子，更煮一二沸，去滓，温服一升，日三服，夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":118,"yaoCount":12,"drinkNum":3,"yaoList":["柴胡","龙骨","黄芩","生姜","人参","桂枝","茯苓","半夏","大黄","牡蛎","大枣","铅丹"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"四两","weight":null,"suffix":null,"showName":"柴胡","extraProcess":null},{"yaoId":"vL3tFGA7NwL","amount":"一两半","weight":null,"suffix":null,"showName":"龙骨","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"一两半","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"一两半","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"一两半","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"一两半（去皮）","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"一两半","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"二合半","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"To31b37bc6Z","amount":"二两","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"MDfiJ4S7u0U","amount":"一两半","weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"六枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"E3Mbs1VE7cx","amount":"一两半","weight":null,"suffix":null,"showName":"铅丹","extraProcess":null}]}}', '2024-12-11