INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2ddJCBzF1Ut', 1, '{"title":"大陷胸丸","description":"<p>$u{大黄}$w{半斤}、$u{葶苈}$w{半斤 (熬)}、$u{芒硝}$w{半斤}、$u{杏仁}$w{半斤 (去皮尖熬)}。</p>\n<p></p>\n<p>         右四味，捣筛二味，纳杏仁、芒硝，合研如脂，和散，取如弹丸一枚，别捣$u{甘遂末}$w{一方寸匙}，$u{白蜜}$w{二合}，水二升，煮取一升，去滓，温顿服之，一宿乃下，如不下，更服，取下为度，禁忌如药法。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":134,"yaoCount":6,"drinkNum":1,"yaoList":["大黄","葶苈","芒硝","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"半斤","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":null,"amount":"半斤 (熬)","weight":null,"suffix":null,"showName":"葶苈","extraProcess":null},{"yaoId":"J7mL6gla0C0","amount":"半斤","weight":null,"suffix":null,"showName":"芒硝","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"半斤 (去皮尖熬)","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null}]}}', '2024-12-14T05:55:03.000Z', '2024-12-14T05:55:03.000Z', '2024-12-14T05:55:03.000Z', '$u{大黄}$w{半斤}、$u{葶苈}$w{半斤 (熬)}、$u{芒硝}$w{半斤}、$u{杏仁}$w{半斤 (去皮尖熬)}。 右四味，捣筛二味，纳杏仁、芒硝，合研如脂，和散，取如弹丸一枚，别捣$u{甘遂末}$w{一方寸匙}，$u{白蜜}$w{二合}，水二升，煮取一升，去滓，温顿服之，一宿乃下，如不下，更服，取下为度，禁忌如药法。', '2024-12-14T05:55:03.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q5xlm41YsjC', 1, '{"title":"大陷胸汤","description":"<p>$u{大黄}$w{六两}、$u{芒硝}$w{一升}、$u{甘遂}$w{一钱 (匙)}。</p>\n<p></p>\n<p>         右三味，以水六升，先煮大黄，取二升，去滓，纳$u{芒硝}，煮二沸，纳$u{甘遂}末，温服一升，得快利，止后服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":135,"yaoCount":3,"drinkNum":2,"yaoList":["大黄","芒硝","甘遂"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"六两","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"J7mL6gla0C0","amount":"一升","weight":null,"suffix":null,"showName":"芒硝","extraProcess":null},{"yaoId":"7nTRDUdzsoW","amount":"一钱 (匙)","weight":null,"suffix":null,"showName":"甘遂","extraProcess":null}]}}', '2024-12-14T06:07:41.000Z', '2024-12-14T06:07:41.000Z', '2024-12-14T06:07:41.000Z', '$u{大黄}$w{六两}、$u{芒硝}$w{一升}、$u{甘遂}$w{一钱 (匙)}。 右三味，以水六升，先煮大黄，取二升，去滓，纳$u{芒硝}，煮二沸，纳$u{甘遂}末，温服一升，得快利，止后服。', '2024-12-14T06:07:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fSO4JXquk35', 1, '{"title":"文蛤散","description":"<p>$u{文蛤}$w{五两}、$u{麻黄}$w{三两}、$u{甘草}$w{三两}、$u{生姜}$w{三两}、$u{石膏}$w{五两}、$u{杏仁}$w{五十粒 (去皮尖)}、$u{大枣}$w{十二枚 (劈)}。</p>\n<p></p>\n<p>        右七味，为散，以沸汤和一方寸匙，汤用五合，调服，假令汗出已，腹中痛者，与$u{芍药}$w{三两}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":136,"yaoCount":7,"drinkNum":1,"yaoList":["文蛤","麻黄","甘草","生姜","石膏","杏仁","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"FCFRnbDhdjZ","amount":"五两","weight":null,"suffix":null,"showName":"文蛤","extraProcess":null},{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"五两","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"五十粒 (去皮尖)","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚 (劈)","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-14T06:43:26.000Z', '2024-12-14T06:43:26.000Z', '2024-12-14T06:43:26.000Z', '$u{文蛤}$w{五两}、$u{麻黄}$w{三两}、$u{甘草}$w{三两}、$u{生姜}$w{三两}、$u{石膏}$w{五两}、$u{杏仁}$w{五十粒 (去皮尖)}、$u{大枣}$w{十二枚 (劈)}。 右七味，为散，以沸汤和一方寸匙，汤用五合，调服，假令汗出已，腹中痛者，与$u{芍药}$w{三两}。', '2024-12-14T06:43:26.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fbDSBTdgLIy', 1, '{"title":"白散","description":"<p>$u{桔梗}$w{三分}、$u{巴豆}$w{一分}、$u{贝母}$w{三分}。</p>\n<p></p>\n<p>        右三味为散，更于臼中杵之，以白饮和服，强人$m{半钱匙}，羸者减之。病在膈上必吐，在膈下必利；不利$m{进热粥一杯}，利不止$n{进冷粥一杯}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":137,"yaoCount":3,"drinkNum":1,"yaoList":["桔梗","巴豆","贝母"],"fangList":[],"fangYaoList":[{"yaoId":"t7DkIvGNO8b","amount":"三分","weight":null,"suffix":null,"showName":"桔梗","extraProcess":null},{"yaoId":"1n7R7kiLFv1","amount":"一分","weight":null,"suffix":null,"showName":"巴豆","extraProcess":null},{"yaoId":"lzOM54GtZJW","amount":"三分","weight":null,"suffix":null,"showName":"贝母","extraProcess":null}]}}', '2024-12-14T06:45:55.000Z', '2024-12-14T06:45:55.000Z', '2024-12-14T06:45:55.000Z', '$u{桔梗}$w{三分}、$u{巴豆}$w{一分}、$u{贝母}$w{三分}。 右三味为散，更于臼中杵之，以白饮和服，强人$m{半钱匙}，羸者减之。病在膈上必吐，在膈下必利；不利$m{进热粥一杯}，利不止$n{进冷粥一杯}。', '2024-12-14T06:45:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aTs1A2nvfd8', 1, '{"title":"柴胡桂枝干姜汤","description":"<p>$u{柴胡}$w{半斤}、$u{桂枝}$w{三两}、$u{干姜}$w{二两}、$u{括蒌根}$w{四两}、$u{黄芩}$w{三两}、$u{牡蛎}$w{二两 (熬)}、$u{甘草}$w{二两 (炙)}。</p>\n<p></p>\n<p>         右七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。初服微烦，复服，汗出便愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":138,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","桂枝","干姜","括蒌根","黄芩","牡蛎","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":null,"suffix":null,"showName":"柴胡","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"二两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"pyZLleBsXOb","amount":"四两","weight":null,"suffix":null,"showName":"括蒌根","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"MDfiJ4S7u0U","amount":"二两 (熬)","weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-14T06:52:26.000Z', '2024-12-14T06:52:26.000Z', '2024-12-14T06:52:26.000Z', '$u{柴胡}$w{半斤}、$u{桂枝}$w{三两}、$u{干姜}$w{二两}、$u{括蒌根}$w{四两}、$u{黄芩}$w{三两}、$u{牡蛎}$w{二两 (熬)}、$u{甘草}$w{二两 (炙)}。 右七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。初服微烦，复服，汗出便愈。', '2024-12-14T06:52:26.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
