INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZjVq47Dubp0', 1, '{"title":"十枣汤","description":"<p>$u{芫花 (熬)}、$u{甘遂}、$u{大戟}。</p>\n<p>          </p>\n<p>        右三味，各$w{等分}，别捣为散，以水一升半，先煮$u{大枣}$w{肥者十枚}，取八合，去滓，纳药末，强人服一钱匙，羸人服半钱，温服之，平旦服，若下少，病不除者，明日更服，加半钱，得快下利后，糜粥自养。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":140,"yaoCount":4,"drinkNum":2,"yaoList":["芫花 (熬)","甘遂","大戟","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"ME53uu1RfSN","amount":null,"weight":null,"suffix":null,"showName":"芫花 (熬)","extraProcess":null},{"yaoId":"7nTRDUdzsoW","amount":null,"weight":null,"suffix":null,"showName":"甘遂","extraProcess":null},{"yaoId":"gZLQX87OyZG","amount":null,"weight":null,"suffix":null,"showName":"大戟","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"肥者十枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-14T07:04:46.000Z', '2024-12-14T07:04:46.000Z', '2024-12-14T07:04:46.000Z', '$u{芫花 (熬)}、$u{甘遂}、$u{大戟}。 右三味，各$w{等分}，别捣为散，以水一升半，先煮$u{大枣}$w{肥者十枚}，取八合，去滓，纳药末，强人服一钱匙，羸人服半钱，温服之，平旦服，若下少，病不除者，明日更服，加半钱，得快下利后，糜粥自养。', '2024-12-14T07:04:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t9HZo6iKq01', 1, '{"title":"大黄黄连黄芩泻心汤","description":"<p>$u{大黄}$w{二两}、$u{黄连}$w{一两}、$u{黄芩}$w{一两}。</p>\n<p></p>\n<p>         右三味，以麻沸汤二升渍之，须臾绞去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":141,"yaoCount":3,"drinkNum":2,"yaoList":["大黄","黄连","黄芩"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"二两","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"5GP5Zyu6577","amount":"一两","weight":null,"suffix":null,"showName":"黄连","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"一两","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null}]}}', '2024-12-14T07:06:41.000Z', '2024-12-14T07:06:41.000Z', '2024-12-14T07:06:41.000Z', '$u{大黄}$w{二两}、$u{黄连}$w{一两}、$u{黄芩}$w{一两}。 右三味，以麻沸汤二升渍之，须臾绞去滓，分温再服。', '2024-12-14T07:06:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
