INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gAPqo2rfu0i', 1, '{"title":"桂枝人参汤","description":"<p>$u{桂枝}$w{四两}、$u{甘草}$w{四两 (炙)}、$u{白术}$w{三两}、$u{人参}$w{三两}、$u{干姜}$w{三两}。</p>\n<p></p>\n<p>         右五味，以水九升，先煮四味，取五升，纳桂枝，更煮取三升，去滓，温服一升，日再服，夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":146,"yaoCount":5,"drinkNum":4,"yaoList":["桂枝","甘草","白术","人参","干姜"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"四两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"四两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null}]}}', '2024-12-14T07:25:08.000Z', '2024-12-14T07:25:08.000Z', '2024-12-14T07:25:08.000Z', '$u{桂枝}$w{四两}、$u{甘草}$w{四两 (炙)}、$u{白术}$w{三两}、$u{人参}$w{三两}、$u{干姜}$w{三两}。 右五味，以水九升，先煮四味，取五升，纳桂枝，更煮取三升，去滓，温服一升，日再服，夜一服。', '2024-12-14T07:25:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('74Ug3dbfuoI', 1, '{"title":"瓜蒂散","description":"<p>$u{瓜蒂}$w{一分 (熬)}、$u{赤小豆}$w{一分}。</p>\n<p></p>\n<p>         右二味，各别捣筛，为散已，合治之，取一钱匙，以$u{香豉}$w{一合}，用热汤七合，煮作稀糜，去津，取汁，和散温顿服之，不吐者，少少加，得快吐乃止。诸亡血，虚家，不可与也。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":147,"yaoCount":3,"drinkNum":1,"yaoList":["瓜蒂","赤小豆"],"fangList":[],"fangYaoList":[{"yaoId":"zdySy9e78kG","amount":"一分 (熬)","weight":null,"suffix":null,"showName":"瓜蒂","extraProcess":null},{"yaoId":"xoqRCmUZylQ","amount":"一分","weight":null,"suffix":null,"showName":"赤小豆","extraProcess":null}]}}', '2024-12-14T07:28:44.000Z', '2024-12-14T07:28:44.000Z', '2024-12-14T07:28:44.000Z', '$u{瓜蒂}$w{一分 (熬)}、$u{赤小豆}$w{一分}。 右二味，各别捣筛，为散已，合治之，取一钱匙，以$u{香豉}$w{一合}，用热汤七合，煮作稀糜，去津，取汁，和散温顿服之，不吐者，少少加，得快吐乃止。诸亡血，虚家，不可与也。', '2024-12-14T07:28:44.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
