INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fHWXBn3FT5V', 1, '{"title":"黄连汤","description":"<p>$u{黄连}$w{三两}、$u{甘草}$w{三两 (炙)}、$u{干姜}$w{三两}、$u{桂枝}$w{三两}、$u{人参}$w{二两}、$u{半夏}$w{半升 (洗)}、$u{大枣}$w{十二枚 (劈)}。</p>\n<p></p>\n<p>        右七味，以水一斗，煮取六升，去滓，温服一升，日三服，夜三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":150,"yaoCount":7,"drinkNum":6,"yaoList":["黄连","甘草","干姜","桂枝","人参","半夏","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"5GP5Zyu6577","amount":"三两","weight":null,"suffix":null,"showName":"黄连","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升 (洗)","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚 (劈)","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-14T07:36:18.000Z', '2024-12-14T07:36:18.000Z', '2024-12-14T07:36:18.000Z', '$u{黄连}$w{三两}、$u{甘草}$w{三两 (炙)}、$u{干姜}$w{三两}、$u{桂枝}$w{三两}、$u{人参}$w{二两}、$u{半夏}$w{半升 (洗)}、$u{大枣}$w{十二枚 (劈)}。 右七味，以水一斗，煮取六升，去滓，温服一升，日三服，夜三服。', '2024-12-14T07:36:18.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BvS0y0h5doY', 1, '{"title":"炙甘草汤","description":"<p>$u{甘草}$w{四两 (炙)}、$u{生姜}$w{三两 (切)}、$u{人参}$w{二两}、$u{地黄}$w{半斤}、$u{桂枝}$w{三两}、$u{麦门冬}$w{半升}、$u{阿胶}$w{二两}、$u{麻仁}$w{半升}、$u{大枣}$w{十二枚 (劈)}。</p>\n<p></p>\n<p>        右九味，以清酒七升，先煮八味，取三升，去滓，纳胶烊消尽，温服一升，日三服。</p>\n<p></p>\n<p>另:$a{桂版。伤寒论-辨咳嗽水饮黄汗历节病脉证并治【炙甘草汤】} $u{地黄}$w{一斤}、$u{大枣}$w{三十枚}。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":151,"yaoCount":9,"drinkNum":3,"yaoList":["甘草","生姜","人参","地黄","桂枝","麦门冬","阿胶","麻仁","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"四两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两 (切)","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"B2o1hdSD6X1","amount":"半斤","weight":null,"suffix":null,"showName":"地黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"DDXydmiFQLK","amount":"半升","weight":null,"suffix":null,"showName":"麦门冬","extraProcess":null},{"yaoId":"T3B7gaA2R03","amount":"二两","weight":null,"suffix":null,"showName":"阿胶","extraProcess":null},{"yaoId":null,"amount":"半升","weight":null,"suffix":null,"showName":"麻仁","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚 (劈)","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2024-12-14T07:38:53.000Z', '2024-12-14T07:38:53.000Z', '2024-12-14T07:38:53.000Z', '$u{甘草}$w{四两 (炙)}、$u{生姜}$w{三两 (切)}、$u{人参}$w{二两}、$u{地黄}$w{半斤}、$u{桂枝}$w{三两}、$u{麦门冬}$w{半升}、$u{阿胶}$w{二两}、$u{麻仁}$w{半升}、$u{大枣}$w{十二枚 (劈)}。 右九味，以清酒七升，先煮八味，取三升，去滓，纳胶烊消尽，温服一升，日三服。 另:$a{桂版。伤寒论-辨咳嗽水饮黄汗历节病脉证并治【炙甘草汤】} $u{地黄}$w{一斤}、$u{大枣}$w{三十枚}。', '2024-12-14T07:38:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SIjmF4uaTXX', 1, '{"title":"猪苓汤","description":"<p>$u{猪苓}$w{一两 (去皮)}、$u{茯苓}$w{一两}、$u{泽泻}$w{一两}、$u{阿胶}$w{一两}、$u{滑石}$w{一两 (碎)}。</p>\n<p></p>\n<p>         右五味，以水四升，先煮四味，取二升，去滓，纳阿胶烊消，温服七合，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":152,"yaoCount":5,"drinkNum":3,"yaoList":["猪苓","茯苓","泽泻","阿胶","滑石"],"fangList":[],"fangYaoList":[{"yaoId":"VBp4qtisnQR","amount":"一两 (去皮)","weight":null,"suffix":null,"showName":"猪苓","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"一两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"TvTXZli2dE7","amount":"一两","weight":null,"suffix":null,"showName":"泽泻","extraProcess":null},{"yaoId":"T3B7gaA2R03","amount":"一两","weight":null,"suffix":null,"showName":"阿胶","extraProcess":null},{"yaoId":"u6WaDjpcWhR","amount":"一两 (碎)","weight":null,"suffix":null,"showName":"滑石","extraProcess":null}]}}', '2024-12-14T09:17:51.000Z', '2024-12-14T09:17:51.000Z', '2024-12-14T09:17:51.000Z', '$u{猪苓}$w{一两 (去皮)}、$u{茯苓}$w{一两}、$u{泽泻}$w{一两}、$u{阿胶}$w{一两}、$u{滑石}$w{一两 (碎)}。 右五味，以水四升，先煮四味，取二升，去滓，纳阿胶烊消，温服七合，日三服。', '2024-12-14T09:17:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jFjVvUZ8RsU', 1, '{"title":"白蜜煎","description":"<p>$u{人参}$w{一两}、$u{地黄}$w{六两}、$u{麻仁}$w{一升}、$u{白蜜}$w{八合}。</p>\n<p></p>\n<p>         右四味，以水一斗，先煎三味，取五升，去滓，纳蜜，再煎一二沸，每服一升，日三夜二。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":153,"yaoCount":4,"drinkNum":5,"yaoList":["人参","地黄","麻仁","白蜜"],"fangList":[],"fangYaoList":[{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"B2o1hdSD6X1","amount":"六两","weight":null,"suffix":null,"showName":"地黄","extraProcess":null},{"yaoId":null,"amount":"一升","weight":null,"suffix":null,"showName":"麻仁","extraProcess":null},{"yaoId":"IHSagd4ikNY","amount":"八合","weight":null,"suffix":null,"showName":"白蜜","extraProcess":null}]}}', '2024-12-14T09:26:46.000Z', '2024-12-14T09:26:46.000Z', '2024-12-14T09:26:46.000Z', '$u{人参}$w{一两}、$u{地黄}$w{六两}、$u{麻仁}$w{一升}、$u{白蜜}$w{八合}。 右四味，以水一斗，先煎三味，取五升，去滓，纳蜜，再煎一二沸，每服一升，日三夜二。', '2024-12-14T09:26:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H5h2MFPBgGZ', 1, '{"title":"大猪胆汁","description":"<p>$u{大猪胆}$w{一枚}。右一味，泄汁，和醋少许，灌谷道中，如一食顷，当大便出宿食甚多。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":154,"yaoCount":1,"drinkNum":1,"yaoList":["大猪胆"],"fangList":[],"fangYaoList":[{"yaoId":"KIP0kUQVkZG","amount":"一枚","weight":null,"suffix":null,"showName":"大猪胆","extraProcess":null}]}}', '2024-12-16T00:52:41.000Z', '2024-12-16T00:52:41.000Z', '2024-12-16T00:52:41.000Z', '$u{大猪胆}$w{一枚}。右一味，泄汁，和醋少许，灌谷道中，如一食顷，当大便出宿食甚多。', '2024-12-16T00:52:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oCWH1dX1rqM', 1, '{"title":"蜜煎导","description":"<p>$u{食蜜}$w{七合}。右一味，纳铜器中，微火煎之，稍凝如饴状，搅之勿令焦着，可丸时，并手捻作挺，令头锐，大如指，长二寸许，当热时急作，冷则鞕，纳谷道中，以手紧抱，欲大便时乃去之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":155,"yaoCount":1,"drinkNum":1,"yaoList":["食蜜"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"七合","weight":null,"suffix":null,"showName":"食蜜","extraProcess":null}]}}', '2024-12-16T00:57:15.000Z', '2024-12-16T00:57:15.000Z', '2024-12-16T00:57:15.000Z', '$u{食蜜}$w{七合}。右一味，纳铜器中，微火煎之，稍凝如饴状，搅之勿令焦着，可丸时，并手捻作挺，令头锐，大如指，长二寸许，当热时急作，冷则鞕，纳谷道中，以手紧抱，欲大便时乃去之。', '2024-12-16T00:57:15.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r7xDdkX6Lvh', 1, '{"title":"茵陈蒿汤","description":"<p>$u{茵陈蒿}$w{六两}、$u{栀子}$w{十四枚 (劈)}、$u{大黄}$w{二两 (去皮)}。</p>\n<p></p>\n<p>         右三味，以水一斗二升，先煮茵陈，减六升，纳二味，煮取三升，去滓，分温三服，小便当利，尿如皂荚汁状，色正赤，一宿病减，黄从小便去也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":156,"yaoCount":3,"drinkNum":3,"yaoList":["茵陈蒿","栀子","大黄"],"fangList":[],"fangYaoList":[{"yaoId":"UCM21bJfrih","amount":"六两","weight":null,"suffix":null,"showName":"茵陈蒿","extraProcess":null},{"yaoId":"7fWzC6yB6Yy","amount":"十四枚 (劈)","weight":null,"suffix":null,"showName":"栀子","extraProcess":null},{"yaoId":"To31b37bc6Z","amount":"二两 (去皮)","weight":null,"suffix":null,"showName":"大黄","extraProcess":null}]}}', '2024-12-16T01:01:12.000Z', '2024-12-16T01:01:12.000Z', '2024-12-16T01:01:12.000Z', '$u{茵陈蒿}$w{六两}、$u{栀子}$w{十四枚 (劈)}、$u{大黄}$w{二两 (去皮)}。 右三味，以水一斗二升，先煮茵陈，减六升，纳二味，煮取三升，去滓，分温三服，小便当利，尿如皂荚汁状，色正赤，一宿病减，黄从小便去也。', '2024-12-16T01:01:12.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IQwNs7PVJAL', 1, '{"title":"小半夏汤","description":"<p>$u{半夏}$w{一升}、$u{生姜}$w{半斤}。</p>\n<p></p>\n<p>        右二味，以水七升，煮取一升半，去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":157,"yaoCount":2,"drinkNum":2,"yaoList":["半夏","生姜"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"一升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"半斤","weight":null,"suffix":null,"showName":"生姜","extraProcess":null}]}}', '2024-12-16T01:14:15.000Z', '2024-12-16T01:14:15.000Z', '2024-12-16T01:14:15.000Z', '$u{半夏}$w{一升}、$u{生姜}$w{半斤}。 右二味，以水七升，煮取一升半，去滓，分温再服。', '2024-12-16T01:14:15.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
