INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f9zm9fNq2ZL', 1, '{"title":"栀子柏皮汤","description":"<p>$u{栀子}$w{十五个 (劈)}、$u{甘草}$w{一两 (炙)}、$u{黄柏}$w{二两}。</p>\n<p></p>\n<p>        右三味，以水四升，煮取一升半，去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":159,"yaoCount":3,"drinkNum":2,"yaoList":["栀子","甘草","黄柏"],"fangList":[],"fangYaoList":[{"yaoId":"7fWzC6yB6Yy","amount":"十五个 (劈)","weight":null,"suffix":null,"showName":"栀子","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"Z5xEswEFq4S","amount":"二两","weight":null,"suffix":null,"showName":"黄柏","extraProcess":null}]}}', '2024-12-16T01:26:28.000Z', '2024-12-16T01:26:28.000Z', '2024-12-16T01:26:28.000Z', '$u{栀子}$w{十五个 (劈)}、$u{甘草}$w{一两 (炙)}、$u{黄柏}$w{二两}。 右三味，以水四升，煮取一升半，去滓，分温再服。', '2024-12-16T01:26:28.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AmvI41avaz6', 1, '{"title":"麻黄连轺赤小豆汤","description":"<p>$u{麻黄}$w{二两}、$u{连轺}$w{二两}、$u{杏仁}$w{四十个 (去皮尖)}、$u{赤小豆}$w{一升}、$u{大枣}$w{十二枚}、$u{生梓白皮}$w{一斤 (切)}、$u{生姜}$w{二两 (切)}、$u{甘草}$w{二两 (炙)}。</p>\n<p></p>\n<p>        右八味，以潦水一斗，先煮麻黄再沸，去上沫，纳诸药，煮取三升，去滓，分温三服，半日服尽。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":160,"yaoCount":8,"drinkNum":3,"yaoList":["麻黄","连轺","杏仁","赤小豆","大枣","生梓白皮","生姜","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"二两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"RCX32XC61We","amount":"二两","weight":null,"suffix":null,"showName":"连轺","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"四十个 (去皮尖)","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null},{"yaoId":"xoqRCmUZylQ","amount":"一升","weight":null,"suffix":null,"showName":"赤小豆","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"WADWMmU3DAz","amount":"一斤 (切)","weight":null,"suffix":null,"showName":"生梓白皮","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"二两 (切)","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2024-12-16T01:29:11.000Z', '2024-12-16T01:29:11.000Z', '2024-12-16T01:29:11.000Z', '$u{麻黄}$w{二两}、$u{连轺}$w{二两}、$u{杏仁}$w{四十个 (去皮尖)}、$u{赤小豆}$w{一升}、$u{大枣}$w{十二枚}、$u{生梓白皮}$w{一斤 (切)}、$u{生姜}$w{二两 (切)}、$u{甘草}$w{二两 (炙)}。 右八味，以潦水一斗，先煮麻黄再沸，去上沫，纳诸药，煮取三升，去滓，分温三服，半日服尽。', '2024-12-16T01:29:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
