INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bAZfkHQXiKs', 1, '{"title":"大建中汤","description":"<p>$u{蜀椒}$w{二合去目汗}、$u{干姜}$w{四两}、$u{人参}$w{一两}、$u{胶饴}$w{一升}。</p>\n<p></p>\n<p>        右四味，以水四升先煮三味，取二升，去滓，纳胶饴，微火煮取一升半，分温再服，如一炊顷，可饮粥二升，后更服，当一日食糜粥，温覆之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":167,"yaoCount":5,"drinkNum":2,"yaoList":["蜀椒","干姜","人参","胶饴"],"fangList":[],"fangYaoList":[{"yaoId":"03dIYYkyQRn","amount":"二合去目汗","weight":null,"suffix":null,"showName":"蜀椒","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"四两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":null,"suffix":null,"showName":"胶饴","extraProcess":null}]}}', '2024-12-16T01:59:15.000Z', '2024-12-16T01:59:15.000Z', '2024-12-16T01:59:15.000Z', '$u{蜀椒}$w{二合去目汗}、$u{干姜}$w{四两}、$u{人参}$w{一两}、$u{胶饴}$w{一升}。 右四味，以水四升先煮三味，取二升，去滓，纳胶饴，微火煮取一升半，分温再服，如一炊顷，可饮粥二升，后更服，当一日食糜粥，温覆之。', '2024-12-16T01:59:15.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
