INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gliLWsylen9', 1, '{"title":"桃花汤","description":"<p>$u{赤石脂}$w{一斤 (一半全用一半筛末)}、$u{干姜}$w{一两}、$u{粳米}$w{一升}。</p>\n<p></p>\n<p>       右三味，以水七升，煮米令熟，去滓，温服七合，纳赤石脂末方寸匙，日三服，若一服愈，余勿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"5IGM9t76quT","no":185,"yaoCount":3,"drinkNum":3,"yaoList":["赤石脂","干姜","粳米"],"fangList":[],"fangYaoList":[{"yaoId":"1rOkrjGOCab","amount":"一斤 (一半全用一半筛末)","weight":null,"suffix":null,"showName":"赤石脂","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"2gRWUBY7CiY","amount":"一升","weight":null,"suffix":null,"showName":"粳米","extraProcess":null}]}}', '2024-12-16T05:45:15.000Z', '2024-12-16T05:45:15.000Z', '2024-12-16T05:45:15.000Z', '$u{赤石脂}$w{一斤 (一半全用一半筛末)}、$u{干姜}$w{一两}、$u{粳米}$w{一升}。 右三味，以水七升，煮米令熟，去滓，温服七合，纳赤石脂末方寸匙，日三服，若一服愈，余勿服。', '2024-12-16T05:45:15.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
